#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio2-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        int val = rand() % 2;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO 2 set to %d\n", val);
        fflush(stdout);

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_SINGLE_0 (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x00 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint16_t config = ADS1115_CONFIG_OS_BEGIN
                    | ADS1115_CONFIG_MUX_SINGLE_0
                    | ADS1115_CONFIG_PGA_4_096V
                    | ADS1115_CONFIG_MODE_SINGLE
                    | ADS1115_CONFIG_DR_128SPS
                    | ADS1115_CONFIG_CQUE_NONE;

    while (running) {
        if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
            perror("write config");
            break;
        }

        usleep(100000);

        uint16_t conv;
        if (i2c_read16(fd, ADS1115_REG_CONVERSION, &conv) < 0) {
            perror("read conversion");
            break;
        }

        int16_t raw = (int16_t)conv;
        printf("Raw: %d\n", raw);
        fflush(stdout);

        usleep(400000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MLX90614_ADDR 0x5a
#define MLX90614_TA 0x06
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mlx90614(int fd, float *ambient_temp) {
    uint8_t reg = MLX90614_TA;
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address 0x%02x: %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *ambient_temp = (float)raw * 0.02f - 273.15f;
    return 0;
}

int main(void) {
    int fd = -1;
    float ambient_temp;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02x: %s\n", MLX90614_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (read_mlx90614(fd, &ambient_temp) == 0) {
            printf("Ambient Temperature: %.2f C\n", ambient_temp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds...\n", POLL_INTERVAL_SEC);
        }
        sleep(POLL_INTERVAL_SEC);
    }

    if (fd >= 0) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

