#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define STEP_US 500000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or permissions)\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int state = 0;
    int increment = 1;

    while (running) {
        if (gpioPWM(PWM_PIN, state) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("PWM duty cycle: %d\n", state);
        fflush(stdout);

        state += increment;
        if (state >= PWM_RANGE) {
            state = PWM_RANGE - 1;
            increment = -1;
        } else if (state <= 0) {
            state = 1;
            increment = 1;
        }

        usleep(STEP_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi using libgpiod.
 *
 * Wiring (BCM numbering):
 *   VCC  -> 5V  (pin 2 or 4)
 *   GND  -> GND (pin 6)
 *   TRIG -> GPIO17 (pin 11)
 *   ECHO -> GPIO27 (pin 13)  [use a voltage divider if your module is 5 V]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 *
 * Run:
 *   ./hcsr04
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define TRIG_PIN  17
#define ECHO_PIN  27

#define TRIG_PULSE_US  10
#define ECHO_TIMEOUT_US 30000   /* 30 ms max echo wait (~5 m round trip) */
#define LOOP_INTERVAL_S 60
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static double elapsed_us(const struct timespec *start, const struct timespec *end)
{
    return (double)(end->tv_sec - start->tv_sec) * 1e6 +
           (double)(end->tv_nsec - start->tv_nsec) / 1e3;
}

static double distance_cm(double elapsed_us)
{
    /* speed of sound ~343 m/s => 0.0343 cm/us; round trip => /2 */
    return elapsed_us * 0.0343 / 2.0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request TRIG as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request ECHO as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. TRIG=GPIO%d, ECHO=GPIO%d. Press Ctrl+C to exit.\n",
           TRIG_PIN, ECHO_PIN);
    fflush(stdout);

    while (g_running) {
        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "TRIG low failed: %s\n", strerror(errno));
            goto cleanup;
        }
        usleep(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "TRIG high failed: %s\n", strerror(errno));
            goto cleanup;
        }
        usleep(TRIG_PULSE_US);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "TRIG low failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* Wait for echo rising edge */
        struct timespec t_start, t_now;
        clock_gettime(CLOCK_MONOTONIC, &t_start);
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "ECHO read failed: %s\n", strerror(errno));
                goto cleanup;
            }
            clock_gettime(CLOCK_MONOTONIC, &t_now);
            if (elapsed_us(&t_start, &t_now) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo start (sensor absent?)\n");
                goto cleanup;
            }
        } while (val == 0);

        /* Measure echo high duration */
        struct timespec t_rise, t_fall;
        clock_gettime(CLOCK_MONOTONIC, &t_rise);

        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "ECHO read failed: %s\n", strerror(errno));
                goto cleanup;
            }
            clock_gettime(CLOCK_MONOTONIC, &t_now);
            if (elapsed_us(&t_rise, &t_now) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                goto cleanup;
            }
        } while (val == 1);

        double elapsed = elapsed_us(&t_rise, &t_now);
        double dist = distance_cm(elapsed);

        if (dist < MIN_DISTANCE_CM || dist > MAX_DISTANCE_CM) {
            fprintf(stderr, "Out-of-range reading: %.2f cm (elapsed %.1f us)\n",
                    dist, elapsed);
        } else {
            printf("Distance: %.2f cm (echo %.1f us)\n", dist, elapsed);
        }
        fflush(stdout);

        /* Sleep LOOP_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < LOOP_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01
#define ADS1115_CONFIG_BASE    0x8000  /* AIN0 single-ended, MUX[14:12]=100 */
#define ADS1115_CONFIG_DR_128  0x0080  /* 128 SPS */
#define ADS1115_CONFIG_CQUE_NONE 0x0003 /* Disable comparator */
#define ADS1115_CONFIG_OS_BEGIN 0x8000 /* Begin single conversion */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    uint16_t config = ADS1115_CONFIG_BASE | ADS1115_CONFIG_DR_128 |
                      ADS1115_CONFIG_CQUE_NONE;
    if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    return 0;
}

static int ads1115_read(int fd, int16_t *value) {
    uint16_t cfg;
    uint16_t raw;

    /* Trigger a single conversion */
    if (i2c_write16(fd, ADS1115_REG_CONFIG, ADS1115_CONFIG_OS_BEGIN) < 0) {
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    /* Read conversion register */
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
        return -1;
    }

    *value = (int16_t)raw;
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    if (ads1115_init(fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("ADS1115 initialized at address 0x%02X. Sampling every 5 s. Ctrl+C to exit.\n",
           ADS1115_ADDR);

    while (g_running) {
        int16_t value;
        if (ads1115_read(fd, &value) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("AIN0: %d\n", value);
        fflush(stdout);

        /* Sleep 5 s, but wake early on signal */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

