#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR        0x40
#define SI7021_CMD_MEAS_RH 0xE5
#define SI7021_CMD_MEAS_T  0xE3
#define I2C_BUS            "/dev/i2c-1"
#define POLL_INTERVAL_SEC  5
#define MEAS_TIMEOUT_MS    100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n", n, len);
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw)
{
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    uint8_t buf[2];
    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += 10) {
        usleep(10000);
        if (i2c_read_bytes(fd, buf, 2) == 0) {
            *raw = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
    }
    fprintf(stderr, "Measurement timed out (cmd 0x%02X)\n", cmd);
    return -1;
}

static float convert_temperature(uint16_t raw)
{
    return (175.72f * raw / 65536.0f) - 46.85f;
}

static float convert_humidity(uint16_t raw)
{
    float rh = (125.0f * raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SI7021 reader started on %s (addr 0x%02X). Press Ctrl+C to stop.\n", I2C_BUS, SI7021_ADDR);

    while (g_running) {
        uint16_t raw_t = 0, raw_rh = 0;

        if (read_measurement(fd, SI7021_CMD_MEAS_T, &raw_t) < 0) {
            fprintf(stderr, "Temperature read failed; continuing.\n");
        } else if (read_measurement(fd, SI7021_CMD_MEAS_RH, &raw_rh) < 0) {
            fprintf(stderr, "Humidity read failed; continuing.\n");
        } else {
            float temp = convert_temperature(raw_t);
            float rh   = convert_humidity(raw_rh);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, rh);
        }

        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_SINGLE_0 (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x00 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) return -1;
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *out = (uint16_t)buf[0] << 8 | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint16_t config = ADS1115_CONFIG_OS_BEGIN
                    | ADS1115_CONFIG_MUX_SINGLE_0
                    | ADS1115_CONFIG_PGA_4_096V
                    | ADS1115_CONFIG_MODE_SINGLE
                    | ADS1115_CONFIG_DR_128SPS
                    | ADS1115_CONFIG_CQUE_NONE;

    for (int i = 0; i < 3 && !g_stop; i++) {
        if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
            perror("write config");
            close(fd);
            return EXIT_FAILURE;
        }

        usleep(100000);

        uint16_t conv;
        if (i2c_read16(fd, ADS1115_REG_CONVERSION, &conv) < 0) {
            perror("read conversion");
            close(fd);
            return EXIT_FAILURE;
        }

        int16_t raw = (int16_t)conv;
        printf("Reading %d: %d\n", i + 1, raw);
        fflush(stdout);

        sleep(1);
    }

    close(fd);
    return EXIT_SUCCESS;
}

