/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi using libgpiod.
 *
 * Wiring (BCM numbering):
 *   VCC  -> 5V  (pin 2 or 4)
 *   GND  -> GND (pin 6)
 *   TRIG -> GPIO17 (pin 11)
 *   ECHO -> GPIO18 (pin 12)  [use a voltage divider if your module is 5 V]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 *
 * Run:
 *   ./hcsr04
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define TRIG_PIN  17
#define ECHO_PIN  18

#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0

#define TRIG_PULSE_US  10
#define ECHO_TIMEOUT_US 30000   /* 30 ms max echo wait (~5 m round trip) */
#define LOOP_DELAY_S   1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(long long us)
{
    struct timespec ts;
    ts.tv_sec  = (time_t)(us / 1000000LL);
    ts.tv_nsec = (long)(us % 1000000LL) * 1000L;
    nanosleep(&ts, NULL);
}

/*
 * Measure distance in cm. Returns -1.0 on timeout or error.
 */
static double measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIG low: %s\n", strerror(errno));
        return -1.0;
    }
    sleep_us(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIG high: %s\n", strerror(errno));
        return -1.0;
    }
    sleep_us(TRIG_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIG low: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge */
    long long t0 = now_us();
    int val;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read ECHO: %s\n", strerror(errno));
            return -1.0;
        }
        if (now_us() - t0 > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo start timeout (sensor absent?)\n");
            return -1.0;
        }
    } while (val == 0);

    long long echo_start = now_us();

    /* Wait for echo falling edge */
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read ECHO: %s\n", strerror(errno));
            return -1.0;
        }
        if (now_us() - echo_start > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo end timeout\n");
            return -1.0;
        }
    } while (val == 1);

    long long echo_end = now_us();
    long long elapsed_us = echo_end - echo_start;

    /* Speed of sound ~343 m/s => 0.0343 cm/us; round trip => /2 */
    double distance = (double)elapsed_us * 0.0343 / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f-%.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }

    return distance;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling for clean exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3/4/5) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        fprintf(stderr, "Error: failed to get TRIG line %d: %s\n", TRIG_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: failed to get ECHO line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request TRIG as output, initial value low */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Error: failed to request TRIG as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request ECHO as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: failed to request ECHO as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. TRIG=GPIO%d, ECHO=GPIO%d. Press Ctrl+C to exit.\n",
           TRIG_PIN, ECHO_PIN);
    fflush(stdout);

    while (g_running) {
        double distance = measure_distance(trig, echo);
        if (distance >= 0.0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: measurement failed\n");
        }
        fflush(stdout);

        /* Sleep in 100 ms increments so we can exit promptly on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            sleep_us(100000);
        }
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

