#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_TIMEOUT_MS 1000

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int setup_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        fprintf(stderr, "Error opening serial port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = (READ_TIMEOUT_MS + 99) / 100;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_serial_line(int fd, char *buf, size_t buf_size) {
    size_t i = 0;
    char ch;
    while (i < buf_size - 1) {
        ssize_t n = read(fd, &ch, 1);
        if (n == 1) {
            if (ch == '\n') {
                buf[i] = '\0';
                return (int)i;
            }
            buf[i++] = ch;
        } else if (n == 0) {
            return -1;
        } else {
            if (errno == EINTR) {
                if (g_stop) return -1;
                continue;
            }
            return -1;
        }
    }
    buf[i] = '\0';
    return (int)i;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = setup_serial(SERIAL_PORT);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    char line[256];
    int bytes_read = read_serial_line(fd, line, sizeof(line));
    if (bytes_read > 0) {
        printf("Received: %s", line);
        fflush(stdout);
    } else if (bytes_read == 0) {
        fprintf(stderr, "Timeout: no data received within %d ms\n", READ_TIMEOUT_MS);
    } else {
        fprintf(stderr, "Error reading from serial port: %s\n", strerror(errno));
    }

    if (close(fd) != 0) {
        fprintf(stderr, "Error closing serial port: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    return (bytes_read > 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

