/*
 * DHT11 reader using libgpiod (modern GPIO character-device API).
 * Board: Raspberry Pi (any model with a BCM GPIO bank).
 * Wiring: DHT11 data pin -> GPIO4 (BCM 4), 4.7k-10k pull-up to 3V3.
 * Build: gcc -O2 -Wall -Wextra -o dht11 dht11.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define DHT11_PIN      4          /* BCM 4 */
#define DHT11_CHIP     "gpiochip4" /* main GPIO bank on Pi 5; use "gpiochip0" on Pi 3/4 */
#define DHT11_TIMEOUT_US 100000   /* 100 ms max wait for any phase */

static volatile sig_atomic_t g_stop = 0;

static void sighandler(int sig)
{
    (void)sig;
    g_stop = 1;
}

/*
 * Wait for the line to reach the requested level, or until the timeout
 * elapses.  Returns 0 on success, -1 on timeout or error.
 */
static int wait_level(struct gpiod_line *line, int level, int timeout_us)
{
    int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (g_stop)
            return -1;
        if (elapsed >= timeout_us)
            return -1;
        usleep(1);
        elapsed++;
    }
    return 0;
}

/*
 * Read 40 bits from the DHT11.
 * Returns 0 on success and fills humidity/temperature; -1 on any error.
 */
static int read_dht11(struct gpiod_line *line, float *humidity, float *temperature)
{
    uint8_t data[5] = {0, 0, 0, 0, 0};

    /* --- Start signal: drive low for >=1 ms, then high --- */
    if (gpiod_line_request_output(line, "dht11", 0) < 0) {
        fprintf(stderr, "request_output failed: %s\n", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "set_value(0) failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);                       /* >1 ms low */

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "set_value(1) failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(30);                         /* 20-40 us high */

    /* --- Switch to input (pull-up brings line high) --- */
    if (gpiod_line_request_input(line, "dht11") < 0) {
        fprintf(stderr, "request_input failed: %s\n", strerror(errno));
        return -1;
    }

    /* --- Sensor response: ~80 us low then ~80 us high --- */
    if (wait_level(line, 0, DHT11_TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for sensor response low.\n");
        return -1;
    }
    if (wait_level(line, 1, DHT11_TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for sensor response high.\n");
        return -1;
    }
    if (wait_level(line, 0, DHT11_TIMEOUT_US) < 0) {
        fprintf(stderr, "Timeout waiting for data start.\n");
        return -1;
    }

    /* --- Read 40 data bits --- */
    for (int i = 0; i < 40; i++) {
        /* Each bit begins with ~50 us low */
        if (wait_level(line, 1, DHT11_TIMEOUT_US) < 0) {
            fprintf(stderr, "Timeout waiting for bit %d high.\n", i);
            return -1;
        }
        /* High duration: ~26-28 us = '0', ~70 us = '1' */
        int high_us = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (g_stop)
                return -1;
            if (high_us >= DHT11_TIMEOUT_US) {
                fprintf(stderr, "Timeout measuring bit %d high duration.\n", i);
                return -1;
            }
            usleep(1);
            high_us++;
        }
        data[i / 8] <<= 1;
        if (high_us > 50)
            data[i / 8] |= 1;
    }

    /* --- Checksum --- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error: computed %u, received %u.\n",
                checksum, data[4]);
        return -1;
    }

    *humidity    = (float)data[0] + (float)data[1] / 10.0f;
    *temperature = (float)data[2] + (float)data[3] / 10.0f;
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int rc = EXIT_FAILURE;

    /* --- Signal handling for clean exit --- */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip --- */
    chip = gpiod_chip_open_by_name(DHT11_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", DHT11_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", DHT11_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- Read once --- */
    float humidity, temperature;
    if (read_dht11(line, &humidity, &temperature) == 0) {
        printf("Humidity: %.1f %%\n", humidity);
        printf("Temperature: %.1f C\n", temperature);
        rc = EXIT_SUCCESS;
    } else {
        fprintf(stderr, "Failed to read DHT11 sensor.\n");
    }

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    return rc;
}

