#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line2 || !line3) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "gpio-cycle", 0) < 0) {
        perror("gpiod_line_request_output line2");
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "gpio-cycle", 0) < 0) {
        perror("gpiod_line_request_output line3");
        goto cleanup;
    }

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value line2 high");
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, 0) < 0) {
            perror("gpiod_line_set_value line3 low");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 2=1, GPIO 3=0\n", i + 1);
        fflush(stdout);

        sleep(CYCLE_DELAY_SEC);

        if (!running) break;

        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value line2 low");
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, 1) < 0) {
            perror("gpiod_line_set_value line3 high");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 2=0, GPIO 3=1\n", i + 1);
        fflush(stdout);

        sleep(CYCLE_DELAY_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

