#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define OPT3001_ADDR 0x44
#define OPT3001_REG_RESULT 0x00
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_REG_LO_THRESH 0x02
#define OPT3001_REG_HI_THRESH 0x03
#define OPT3001_REG_MANUFACTURER 0x7E
#define OPT3001_REG_DEVICE_ID 0x7F

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int i2c_read_reg(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val & 0xFF);
    buf[2] = (uint8_t)((val >> 8) & 0xFF);
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int opt3001_init(int fd) {
    uint16_t config;
    if (i2c_read_reg(fd, OPT3001_REG_CONFIG, &config) < 0) {
        return -1;
    }
    if ((config & 0x0001) == 0) {
        return 0;
    }
    if (i2c_read_reg(fd, OPT3001_REG_MANUFACTURER, &config) < 0) {
        return -1;
    }
    if ((config & 0x0F) != 0x0D) {
        fprintf(stderr, "Warning: Manufacturer ID mismatch (0x%02X)\n", config & 0x0F);
    }
    if (i2c_read_reg(fd, OPT3001_REG_DEVICE_ID, &config) < 0) {
        return -1;
    }
    if ((config & 0xFF) != 0x01) {
        fprintf(stderr, "Warning: Device ID mismatch (0x%02X)\n", config & 0xFF);
    }
    return 0;
}

static int opt3001_read_lux(int fd, float *lux) {
    uint16_t raw;
    if (i2c_read_reg(fd, OPT3001_REG_RESULT, &raw) < 0) {
        return -1;
    }
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux = (float)mantissa * (0.01f * (1 << exponent));
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", OPT3001_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (opt3001_init(fd) < 0) {
        fprintf(stderr, "Error initializing OPT3001: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    float lux;
    if (opt3001_read_lux(fd, &lux) < 0) {
        fprintf(stderr, "Error reading lux: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    printf("Lux: %.2f\n", lux);
    close(fd);
    return 0;
}

