#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_TIMEOUT_MS 1000
#define MAX_RETRIES 3

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int setup_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    if (fcntl(fd, F_SETFL, 0) == -1) {
        perror("fcntl F_SETFL");
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHONL | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = READ_TIMEOUT_MS / 100;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_serial_line(int fd, char *buf, size_t buf_size) {
    size_t total = 0;
    char ch;
    int retries = 0;

    while (total < buf_size - 1) {
        ssize_t n = read(fd, &ch, 1);
        if (n == 1) {
            if (ch == '\n') {
                buf[total] = '\0';
                return (int)total;
            }
            buf[total++] = ch;
        } else if (n == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                if (g_stop) return -1;
                if (++retries > MAX_RETRIES) {
                    fprintf(stderr, "Timeout: no data after %d retries\n", MAX_RETRIES);
                    return -1;
                }
                usleep(10000);
                continue;
            }
            perror("read");
            return -1;
        } else {
            if (g_stop) return -1;
            if (++retries > MAX_RETRIES) {
                fprintf(stderr, "Timeout: read returned 0 after %d retries\n", MAX_RETRIES);
                return -1;
            }
            usleep(10000);
        }
    }

    buf[total] = '\0';
    return (int)total;
}

int main(void) {
    if (setup_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    int fd = init_serial(SERIAL_PORT);
    if (fd == -1) {
        fprintf(stderr, "Failed to initialize serial port %s\n", SERIAL_PORT);
        return EXIT_FAILURE;
    }

    printf("Serial port %s initialized. Waiting for data...\n", SERIAL_PORT);

    char line[256];
    int result = read_serial_line(fd, line, sizeof(line));

    if (result > 0) {
        printf("Received: %s", line);
    } else if (result == 0) {
        fprintf(stderr, "No data received within timeout.\n");
    } else {
        fprintf(stderr, "Failed to read from serial port.\n");
    }

    if (close(fd) == -1) {
        perror("close");
        return EXIT_FAILURE;
    }

    printf("Serial port closed.\n");
    return (result > 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

