#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_17 17
#define PWM_PIN_18 18
#define PWM_PIN_27 27
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define SLEEP_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure all three pins as hardware-PWM outputs */
    int pins[] = {PWM_PIN_17, PWM_PIN_18, PWM_PIN_27};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int val = 0; val <= PWM_RANGE && running; ++val) {
            for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
                if (gpioPWM(pins[i], val) != 0) {
                    fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            }
            printf("PWM 17=%d 18=%d 27=%d\n", val, val, val);
            fflush(stdout);
            gpioDelay(10000); /* 10 ms */
        }
        for (int val = PWM_RANGE; val >= 0 && running; --val) {
            for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
                if (gpioPWM(pins[i], val) != 0) {
                    fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                    gpioTerminate();
                    return EXIT_FAILURE;
                }
            }
            printf("PWM 17=%d 18=%d 27=%d\n", val, val, val);
            fflush(stdout);
            gpioDelay(10000);
        }
    }

    /* Clean shutdown: turn off PWM and release pigpio */
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DIR "/sys/bus/w1/devices"
#define MAX_DEVICES 16
#define READ_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int scan_devices(char devices[][64], int max, int *count) {
    FILE *fp = fopen(W1_DIR "/w1_master_slaves", "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", W1_DIR "/w1_master_slaves", strerror(errno));
        return -1;
    }

    char line[256];
    *count = 0;
    while (fgets(line, sizeof(line), fp) != NULL && *count < max) {
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') line[len - 1] = '\0';
        if (len > 0 && line[len - 1] == '\r') line[len - 1] = '\0';
        if (len > 0) {
            strncpy(devices[*count], line, sizeof(devices[*count]) - 1);
            devices[*count][sizeof(devices[*count]) - 1] = '\0';
            (*count)++;
        }
    }

    fclose(fp);
    return 0;
}

static float read_temperature(const char *device_id) {
    char path[128];
    snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_DIR, device_id);

    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1000.0f;
    }

    char line1[256];
    char line2[256];

    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1000.0f;
    }
    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "Device %s: CRC check failed (no YES)\n", device_id);
        return -1000.0f;
    }

    char *temp_str = strstr(line2, "t=");
    if (!temp_str) {
        fprintf(stderr, "Device %s: temperature data not found\n", device_id);
        return -1000.0f;
    }

    long temp_reading = strtol(temp_str + 2, NULL, 10);
    if (temp_reading == 0 && errno == EINVAL) {
        fprintf(stderr, "Device %s: invalid temperature value\n", device_id);
        return -1000.0f;
    }

    return (float)temp_reading / 1000.0f;
}

int main(void) {
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    char devices[MAX_DEVICES][64];
    int num_devices = 0;

    if (scan_devices(devices, MAX_DEVICES, &num_devices) != 0) {
        return EXIT_FAILURE;
    }

    if (num_devices == 0) {
        fprintf(stderr, "No DS18B20 devices found on GPIO 4, 17, or 18.\n");
        fprintf(stderr, "Check wiring and that w1-gpio (or w1-osc) overlay is loaded.\n");
        return EXIT_FAILURE;
    }

    printf("Found %d DS18B20 sensor(s). Reading every %d seconds. Press Ctrl+C to exit.\n",
           num_devices, READ_INTERVAL);

    while (g_running) {
        for (int i = 0; i < num_devices && g_running; i++) {
            float temperature = read_temperature(devices[i]);
            if (temperature > -999.0f) {
                printf("Temperature from %s: %.2f C\n", devices[i], temperature);
            } else {
                fprintf(stderr, "Failed to read temperature from %s\n", devices[i]);
            }
        }
        if (g_running) {
            sleep(READ_INTERVAL);
        }
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define HTU21D_ADDR 0x40
#define I2C_DEV "/dev/i2c-1"
#define MEASURE_TEMP_HOLD 0xE3
#define MEASURE_HUMID_HOLD 0xE5
#define RESET_CMD 0xFE
#define TEMP_CONV_US 50000
#define HUMID_CONV_US 50000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, uint8_t cmd) {
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint32_t *raw) {
    if (i2c_write(fd, cmd) < 0) return -1;
    usleep(TEMP_CONV_US);
    uint8_t buf[3];
    if (i2c_read(fd, buf, 3) < 0) return -1;
    uint32_t val = ((uint32_t)buf[0] << 8) | buf[1];
    val &= 0xFFFC;
    *raw = val;
    return 0;
}

static float convert_temperature(uint32_t raw) {
    return -46.85 + 175.72 * (float)raw / 65536.0;
}

static float convert_humidity(uint32_t raw) {
    float h = -6.0 + 125.0 * (float)raw / 65536.0;
    if (h < 0.0) h = 0.0;
    if (h > 100.0) h = 100.0;
    return h;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t chip_id;
    if (i2c_read(fd, &chip_id, 1) < 0) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        close(fd);
        return 1;
    }
    if (chip_id != 0xE5) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0xE5)\n", chip_id);
        close(fd);
        return 1;
    }

    while (g_running) {
        uint32_t raw_t, raw_h;
        if (read_measurement(fd, MEASURE_TEMP_HOLD, &raw_t) < 0) {
            fprintf(stderr, "Temperature read failed\n");
            break;
        }
        if (read_measurement(fd, MEASURE_HUMID_HOLD, &raw_h) < 0) {
            fprintf(stderr, "Humidity read failed\n");
            break;
        }
        float temp = convert_temperature(raw_t);
        float hum = convert_humidity(raw_h);
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        fflush(stdout);
        for (int i = 0; i < 60 && g_running; i++) {
            sleep(1);
        }
    }

    i2c_write(fd, RESET_CMD);
    close(fd);
    return 0;
}

