#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24
#define CHIP_NAME "gpiochip0"
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_ms(unsigned int ms) {
    struct timespec ts = {
        .tv_sec = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4];
    const unsigned int pins[4] = {DHT22_PIN_1, DHT22_PIN_2, DHT22_PIN_3, DHT22_PIN_4};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], "dht22", 0) < 0) {
            fprintf(stderr, "Failed to request output for GPIO %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %u high: %s\n", pins[i], strerror(errno));
                goto cleanup;
            }
        }
        sleep_ms(1000);
        for (int i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %u low: %s\n", pins[i], strerror(errno));
                goto cleanup;
            }
        }
        sleep_ms(1000);
        printf("GPIO %u, %u, %u, %u set HIGH then LOW\n", DHT22_PIN_1, DHT22_PIN_2, DHT22_PIN_3, DHT22_PIN_4);
        fflush(stdout);
        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 255
#define STEP_US 500000  /* 0.5 s */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

int main(void) {
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or not running?)\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pins as hardware-PWM outputs --- */
    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set PWM range (0..255) --- */
    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_3);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main loop: sweep 0..255 repeatedly --- */
    while (g_running) {
        for (int i = 0; i <= PWM_RANGE && g_running; i++) {
            if (gpioPWM(PWM_PIN_1, i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_1);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (gpioPWM(PWM_PIN_2, i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_2);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (gpioPWM(PWM_PIN_3, i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_3);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM: GPIO%d=%d, GPIO%d=%d, GPIO%d=%d\n",
                   PWM_PIN_1, i, PWM_PIN_2, i, PWM_PIN_3, i);
            fflush(stdout);
            gpioDelay(STEP_US);
        }
        for (int i = PWM_RANGE; i >= 0 && g_running; i--) {
            if (gpioPWM(PWM_PIN_1, i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_1);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (gpioPWM(PWM_PIN_2, i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_2);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (gpioPWM(PWM_PIN_3, i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_3);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM: GPIO%d=%d, GPIO%d=%d, GPIO%d=%d\n",
                   PWM_PIN_1, i, PWM_PIN_2, i, PWM_PIN_3, i);
            fflush(stdout);
            gpioDelay(STEP_US);
        }
    }

    /* --- Clean shutdown: turn off PWM and release pigpio --- */
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

