#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_COMMAND_BIT), value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    uint8_t cmd = (uint8_t)(reg | TCS34725_COMMAND_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000);
    if (i2c_write(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write(fd, TCS34725_CONTROL, 0xFF) < 0) return -1;
    if (i2c_write(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;
    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t c, r, g, b;
    if (i2c_read(fd, TCS34725_CDATA, &c) < 0) return -1;
    if (i2c_read(fd, TCS34725_RDATA, &r) < 0) return -1;
    if (i2c_read(fd, TCS34725_GDATA, &g) < 0) return -1;
    if (i2c_read(fd, TCS34725_BDATA, &b) < 0) return -1;
    *clear = (uint16_t)c;
    *red = (uint16_t)r;
    *green = (uint16_t)g;
    *blue = (uint16_t)b;
    return 0;
}

int main(void) {
    int fd = -1;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", TCS34725_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "Error initializing TCS34725 sensor.\n");
        close(fd);
        return 1;
    }

    while (g_running) {
        uint16_t clear, red, green, blue;
        if (tcs34725_read_data(fd, &clear, &red, &green, &blue) == 0) {
            printf("C: %5u, R: %5u, G: %5u, B: %5u\n", clear, red, green, blue);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }
        usleep(200000);
    }

    if (fd >= 0) {
        i2c_write(fd, TCS34725_ENABLE, 0x00);
        close(fd);
    }
    return 0;
}

