/*
 * capture.c - Capture a single image from the Raspberry Pi camera module
 * using the linux-v4l2 stack, and save it to a file.
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture capture.c -lv4l2
 * Run:    ./capture output.jpg
 *
 * The program opens /dev/video0, sets the format to YUYV, requests a
 * 640x480 preview-size buffer, and captures one frame.  It then writes
 * the raw YUYV data to the output file.  On any error the program
 * reports the problem and exits with a non-zero status.  The device is
 * released on every exit path.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FRAME_SIZE (WIDTH * HEIGHT * 2)   /* YUYV: 2 bytes/pixel */

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <output_file>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *output_file = argv[1];

    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Open the video device --- */
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Set format: YUYV, 640x480 --- */
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Camera does not support YUYV format.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Request a single buffer --- */
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory on %s.\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Query and map the buffer --- */
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    void *buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                              MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Queue the buffer --- */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Start streaming --- */
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Dequeue one frame --- */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (g_stop) {
        fprintf(stderr, "Interrupted before capture.\n");
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Write raw YUYV data to file --- */
    FILE *fp = fopen(output_file, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n",
                output_file, strerror(errno));
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    size_t written = fwrite(buffer_start, 1, FRAME_SIZE, fp);
    if (written != FRAME_SIZE) {
        fprintf(stderr, "Error writing image data: %s\n",
                written == 0 ? "file write failed" : "short write");
        fclose(fp);
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", output_file, strerror(errno));
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    /* --- Clean shutdown --- */
    xioctl(fd, VIDIOC_STREAMOFF, &type);
    munmap(buffer_start, buf.length);
    close(fd);

    printf("Captured %d x %d YUYV image and saved to %s\n",
           WIDTH, HEIGHT, output_file);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_22 22
#define GPIO_27 27
#define CONSUMER "gpio_toggle"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line22 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line22 = gpiod_chip_get_line(chip, GPIO_22);
    if (!line22) {
        perror("gpiod_chip_get_line(22)");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line(27)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line22, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(22)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(27)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line22, 1) < 0) {
            perror("gpiod_line_set_value(22,1)");
            break;
        }
        if (gpiod_line_set_value(line27, 0) < 0) {
            perror("gpiod_line_set_value(27,0)");
            break;
        }
        printf("GPIO 22: 1, GPIO 27: 0\n");
        fflush(stdout);
        usleep(10000);

        if (!running) break;

        if (gpiod_line_set_value(line22, 0) < 0) {
            perror("gpiod_line_set_value(22,0)");
            break;
        }
        if (gpiod_line_set_value(line27, 1) < 0) {
            perror("gpiod_line_set_value(27,1)");
            break;
        }
        printf("GPIO 22: 0, GPIO 27: 1\n");
        fflush(stdout);
        usleep(10000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line22) gpiod_line_release(line22);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, const unsigned char *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ssd1306_send_command(int fd, unsigned char cmd) {
    unsigned char buf[2] = {0x00, cmd};
    return i2c_write(fd, buf, 2);
}

static int ssd1306_send_data(int fd, const unsigned char *data, size_t len) {
    unsigned char *buf = malloc(len + 1);
    if (!buf) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    buf[0] = 0x40;
    memcpy(buf + 1, data, len);
    int ret = i2c_write(fd, buf, len + 1);
    free(buf);
    return ret;
}

static int ssd1306_init(int fd) {
    unsigned char init_cmds[] = {
        0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40,
        0x8D, 0x14, 0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12,
        0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6,
        0xAF
    };
    for (size_t i = 0; i < sizeof(init_cmds); i++) {
        if (ssd1306_send_command(fd, init_cmds[i]) < 0) return -1;
    }
    return 0;
}

static int ssd1306_clear(int fd) {
    unsigned char *buf = malloc(SSD1306_WIDTH * (SSD1306_HEIGHT / 8));
    if (!buf) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    memset(buf, 0, SSD1306_WIDTH * (SSD1306_HEIGHT / 8));
    if (ssd1306_send_data(fd, buf, SSD1306_WIDTH * (SSD1306_HEIGHT / 8)) < 0) {
        free(buf);
        return -1;
    }
    free(buf);
    return 0;
}

static int ssd1306_display_text(int fd, const char *text) {
    unsigned char *buf = malloc(SSD1306_WIDTH * (SSD1306_HEIGHT / 8));
    if (!buf) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    memset(buf, 0, SSD1306_WIDTH * (SSD1306_HEIGHT / 8));
    size_t len = strlen(text);
    if (len > SSD1306_WIDTH) len = SSD1306_WIDTH;
    for (size_t i = 0; i < len; i++) {
        // Simplified: write ASCII character codes directly (monospace placeholder)
        buf[i] = (unsigned char)text[i];
    }
    if (ssd1306_send_data(fd, buf, SSD1306_WIDTH * (SSD1306_HEIGHT / 8)) < 0) {
        free(buf);
        return -1;
    }
    free(buf);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    if (ssd1306_init(fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed\n");
        close(fd);
        return 1;
    }

    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "SSD1306 clear failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        if (ssd1306_display_text(fd, "Hello, World!") < 0) {
            fprintf(stderr, "Failed to display text\n");
            break;
        }
        usleep(100000);
    }

    ssd1306_clear(fd);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5
#define NUM_PINS 3
#define DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS] = {NULL};
    int pins[NUM_PINS] = {GPIO_2, GPIO_3, GPIO_5};
    int i;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio_control", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("GPIO %d set HIGH\n", pins[i]);
        }
        sleep(DELAY_SEC);

        for (i = 0; i < NUM_PINS; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("GPIO %d set LOW\n", pins[i]);
        }
        sleep(DELAY_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure pins as hardware-PWM outputs */
    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 255 for 8-bit resolution */
    if (gpioSetPWMrange(PWM_PIN_1, 255) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, 255) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, 255) != 0 ||
        gpioSetPWMrange(PWM_PIN_4, 255) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int state = 0;

    while (running) {
        switch (state) {
            case 0:
                gpioPWM(PWM_PIN_1, 255);
                gpioPWM(PWM_PIN_2, 0);
                gpioPWM(PWM_PIN_3, 0);
                gpioPWM(PWM_PIN_4, 0);
                printf("State 0: PWM1=255 PWM2=0 PWM3=0 PWM4=0\n");
                break;
            case 1:
                gpioPWM(PWM_PIN_1, 0);
                gpioPWM(PWM_PIN_2, 255);
                gpioPWM(PWM_PIN_3, 0);
                gpioPWM(PWM_PIN_4, 0);
                printf("State 1: PWM1=0 PWM2=255 PWM3=0 PWM4=0\n");
                break;
            case 2:
                gpioPWM(PWM_PIN_1, 0);
                gpioPWM(PWM_PIN_2, 0);
                gpioPWM(PWM_PIN_3, 255);
                gpioPWM(PWM_PIN_4, 0);
                printf("State 2: PWM1=0 PWM2=0 PWM3=255 PWM4=0\n");
                break;
            case 3:
                gpioPWM(PWM_PIN_1, 0);
                gpioPWM(PWM_PIN_2, 0);
                gpioPWM(PWM_PIN_3, 0);
                gpioPWM(PWM_PIN_4, 255);
                printf("State 3: PWM1=0 PWM2=0 PWM3=0 PWM4=255\n");
                break;
        }
        state = (state + 1) % 4;

        /* Sleep 1 second, but wake early on signal */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean shutdown: turn off all PWM outputs */
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define OUTPUT_PIN  24
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  30000  /* 30 ms max echo wait */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *out = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    out  = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!trig || !echo || !out) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("request trigger output");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("request echo input");
        goto cleanup;
    }
    if (gpiod_line_request_output(out, "hcsr04-out", 0) < 0) {
        perror("request output");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger is low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low");
            break;
        }
        usleep(2);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("set trigger high");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("set trigger low");
            break;
        }

        /* Wait for echo rising edge */
        long long t0 = now_us();
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo");
                goto cleanup;
            }
            if (now_us() - t0 > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                goto cleanup;
            }
        } while (val == 0);

        /* Measure echo high duration */
        long long rise = now_us();
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("read echo");
                goto cleanup;
            }
            if (now_us() - rise > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                goto cleanup;
            }
        } while (val == 1);

        long long elapsed = now_us() - rise;
        float distance = (float)elapsed / 58.0f;

        if (gpiod_line_set_value(out, (distance > 2.0f) ? 1 : 0) < 0) {
            perror("set output");
            break;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);
        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (out)  gpiod_line_release(out);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers.\n");
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWrite(GPIO_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to write HIGH to GPIO %d.\n", GPIO_PIN);
            break;
        }
        gpioDelay(DELAY_US);

        if (!running) break;

        if (gpioWrite(GPIO_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to write LOW to GPIO %d.\n", GPIO_PIN);
            break;
        }
        gpioDelay(DELAY_US);
    }

    /* Ensure pin is left LOW on exit */
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

