#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define CAPTURE_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    void *buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = CAPTURE_INTERVAL_US;
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select failed: %s\n", strerror(errno));
            break;
        }
        if (r == 0) continue;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            break;
        }

        FILE *fp = fopen("captured_image.jpg", "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        } else {
            size_t bytes_written = fwrite(buffer_start, 1, buf.bytesused, fp);
            if (bytes_written != buf.bytesused) {
                fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
            }
            fclose(fp);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            break;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
    }
    munmap(buffer_start, buf.length);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7

#define BME280_CHIP_ID 0x60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BME280_REG_ID, &id) < 0) {
        fprintf(stderr, "Error reading chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BME280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", id, BME280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error resetting BME280: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    uint8_t status;
    int retries = 10;
    do {
        if (i2c_read_reg(fd, BME280_REG_STATUS, &status) < 0) return -1;
        if (status & 0x01) break;
        usleep(2000);
    } while (--retries > 0);

    if (retries == 0) {
        fprintf(stderr, "BME280 reset timeout\n");
        return -1;
    }

    if (i2c_write_reg(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write_reg(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read(int fd, float *temp, float *hum) {
    uint8_t data[8];
    if (i2c_read_block(fd, BME280_REG_DATA, data, 8) < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    int32_t raw_temp = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_hum = (data[6] << 8) | data[7];

    *temp = ((float)raw_temp / 1024.0) * 5.0 - 40.0;
    *hum = ((float)raw_hum / 1024.0) * 100.0;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(fd);
        return 1;
    }

    printf("BME280 initialized. Reading every 5 seconds...\n");

    while (running) {
        float temp, hum;
        if (bme280_read(fd, &temp, &hum) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        } else {
            fprintf(stderr, "Read failed, continuing...\n");
        }
        sleep(5);
    }

    printf("\nExiting...\n");
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

#define ADS1115_CONFIG_OS_BEGIN (1 << 15)
#define ADS1115_CONFIG_MUX_SINGLE_0 (0x04 << 12)
#define ADS1115_CONFIG_PGA_4_096V (0x01 << 9)
#define ADS1115_CONFIG_MODE_SINGLE (0x01 << 8)
#define ADS1115_CONFIG_DR_128SPS (0x00 << 5)
#define ADS1115_CONFIG_CQUE_NONE (0x03 << 0)

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *val = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        goto cleanup;
    }

    uint16_t config = ADS1115_CONFIG_OS_BEGIN
                    | ADS1115_CONFIG_MUX_SINGLE_0
                    | ADS1115_CONFIG_PGA_4_096V
                    | ADS1115_CONFIG_MODE_SINGLE
                    | ADS1115_CONFIG_DR_128SPS
                    | ADS1115_CONFIG_CQUE_NONE;

    if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Failed to write ADS1115 config: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        usleep(200000);

        if (i2c_write16(fd, ADS1115_REG_CONFIG, config) < 0) {
            fprintf(stderr, "Failed to trigger conversion: %s\n", strerror(errno));
            goto cleanup;
        }

        usleep(10000);

        uint16_t raw;
        if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
            fprintf(stderr, "Failed to read conversion: %s\n", strerror(errno));
            goto cleanup;
        }

        int16_t adc_value = (int16_t)raw;
        printf("ADC Value: %d\n", adc_value);
        fflush(stdout);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 4
#define PERIOD_SEC 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value high");
            goto cleanup;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        if (!running) break;

        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value low");
            goto cleanup;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        for (int i = 0; i < PERIOD_SEC && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
