#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define SAMPLE_PERIOD_US 10000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    usleep(100000);

    while (g_running) {
        int16_t ax, ay, az;
        if (read_accel(fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Error reading accelerometer: %s\n", strerror(errno));
            break;
        }
        printf("Accel: X=%d, Y=%d, Z=%d\n", ax, ay, az);
        usleep(SAMPLE_PERIOD_US);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 23
#define PERIOD_MS 50

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    int val = 0;
    while (running) {
        val = !val;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, val);
        fflush(stdout);
        usleep(PERIOD_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define LCD_ADDR 0x27
#define LCD_WIDTH 16

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t *data, size_t len) {
    if (write(fd, data, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void lcd_pulse_enable(int fd, uint8_t data) {
    uint8_t buf[2];
    buf[0] = data | 0x04;
    buf[1] = data | 0x05;
    i2c_write(fd, buf, 2);
}

static void lcd_send_nibble(int fd, uint8_t nibble, int is_data) {
    uint8_t rs = is_data ? 0x01 : 0x00;
    uint8_t nibble_with_rs = (nibble & 0xF0) | rs;
    lcd_pulse_enable(fd, nibble_with_rs);
}

static void lcd_send_byte(int fd, uint8_t value, int is_data) {
    lcd_send_nibble(fd, value & 0xF0, is_data);
    lcd_send_nibble(fd, (value << 4) & 0xF0, is_data);
}

static void lcd_command(int fd, uint8_t cmd) {
    lcd_send_byte(fd, cmd, 0);
}

static void lcd_data(int fd, uint8_t data) {
    lcd_send_byte(fd, data, 1);
}

static void lcd_init(int fd) {
    usleep(50000);
    lcd_send_nibble(fd, 0x30, 0);
    usleep(5000);
    lcd_send_nibble(fd, 0x30, 0);
    usleep(100);
    lcd_send_nibble(fd, 0x30, 0);
    usleep(100);
    lcd_send_nibble(fd, 0x20, 0);
    usleep(100);
    lcd_command(fd, 0x28);
    lcd_command(fd, 0x08);
    lcd_command(fd, 0x01);
    usleep(2000);
    lcd_command(fd, 0x06);
    lcd_command(fd, 0x0C);
}

static void lcd_clear(int fd) {
    lcd_command(fd, 0x01);
    usleep(2000);
}

static void lcd_set_cursor(int fd, int col, int row) {
    uint8_t addr = (row == 0) ? (0x80 + col) : (0xC0 + col);
    lcd_command(fd, addr);
}

static void lcd_write_string(int fd, const char *str) {
    while (*str) {
        lcd_data(fd, (uint8_t)*str++);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LCD_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    lcd_init(fd);
    lcd_clear(fd);

    while (running) {
        char line[LCD_WIDTH + 1];
        snprintf(line, sizeof(line), "Hello, World!");
        lcd_clear(fd);
        lcd_set_cursor(fd, 0, 0);
        lcd_write_string(fd, line);
        sleep(10);
    }

    lcd_clear(fd);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define I2C_BUS "/dev/i2c-1"
#define NUM_READINGS 100

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from register 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_mpu6050(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_REG_ACCEL_XOUT_H, buf, 6) < 0) {
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_byte(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU6050 not detected or not responding.\n");
        close(fd);
        return 1;
    }

    int16_t ax, ay, az;
    int exit_code = 0;

    for (int i = 0; i < NUM_READINGS && !g_stop; i++) {
        if (read_mpu6050(fd, &ax, &ay, &az) < 0) {
            exit_code = 1;
            break;
        }
        printf("Reading %d: X=%d, Y=%d, Z=%d\n", i + 1, ax, ay, az);
        fflush(stdout);
    }

    if (g_stop) {
        fprintf(stderr, "\nInterrupted by signal.\n");
    }

    if (close(fd) < 0) {
        fprintf(stderr, "Error closing I2C device: %s\n", strerror(errno));
        exit_code = 1;
    }

    return exit_code;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_14 14
#define GPIO_15 15
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line14 = gpiod_chip_get_line(chip, GPIO_14);
    if (!line14) {
        perror("gpiod_chip_get_line (GPIO 14)");
        goto cleanup;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_15);
    if (!line15) {
        perror("gpiod_chip_get_line (GPIO 15)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line14, "gpio14-toggle", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 14)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line15, "gpio15-toggle", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 15)");
        goto cleanup;
    }

    while (running) {
        int val14 = gpiod_line_get_value(line14);
        if (val14 < 0) {
            perror("gpiod_line_get_value (GPIO 14)");
            goto cleanup;
        }

        int val15 = gpiod_line_get_value(line15);
        if (val15 < 0) {
            perror("gpiod_line_get_value (GPIO 15)");
            goto cleanup;
        }

        if (val14 != val15) {
            fprintf(stderr, "Error: GPIO 14 and GPIO 15 have different states (%d vs %d).\n", val14, val15);
            goto cleanup;
        }

        if (gpiod_line_set_value(line14, val14 == 0 ? 1 : 0) < 0) {
            perror("gpiod_line_set_value (GPIO 14)");
            goto cleanup;
        }

        if (gpiod_line_set_value(line15, val15 == 0 ? 1 : 0) < 0) {
            perror("gpiod_line_set_value (GPIO 15)");
            goto cleanup;
        }

        printf("GPIO 14: %d, GPIO 15: %d\n", val14, val15);
        fflush(stdout);

        for (int i = 0; i < POLL_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line14) gpiod_line_release(line14);
    if (line15) gpiod_line_release(line15);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID      "rpi_sensor_publisher"
#define MQTT_TOPIC          "sensor/data"
#define SENSOR_PIN          4
#define SAMPLE_PERIOD_US    10000  /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a sensor value from the specified GPIO pin.
 * Returns 0 on success, -1 on error.
 */
static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return value;
}

/*
 * Validate the sensor reading.
 * Returns true if the reading is within the expected range, false otherwise.
 */
static bool validate_sensor_data(int sensor_value)
{
    return (sensor_value >= 0 && sensor_value <= 1);
}

/*
 * Format the sensor data into a JSON string.
 * Returns a newly allocated string (caller must free), or NULL on error.
 */
static char *format_sensor_data(int sensor_value)
{
    char *json_string = malloc(64);
    if (json_string == NULL) {
        fprintf(stderr, "Error allocating memory for JSON string: %s\n", strerror(errno));
        return NULL;
    }

    snprintf(json_string, 64, "{\"sensor_value\": %d}", sensor_value);
    return json_string;
}

/*
 * Publish the sensor data to the MQTT broker.
 * Returns 0 on success, -1 on error.
 */
static int publish_sensor_data(MQTTClient client, const char *topic, const char *payload)
{
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    pubmsg.payload = (void *)payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    if (MQTTClient_publishMessage(client, topic, &pubmsg, &token) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(MQTTClient_getLastError()));
        return -1;
    }

    MQTTClient_waitForCompletion(client, token, 1000L);
    return 0;
}

int main(void)
{
    MQTTClient client;
    int rc;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pin as input */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as input\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MQTT client */
    if ((rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS,
                                MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Connect to MQTT broker */
    if ((rc = MQTTClient_connect(client, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Connected to MQTT broker at %s\n", MQTT_BROKER_ADDRESS);

    /* Main loop */
    while (g_running) {
        int sensor_value = read_sensor(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Sensor read failed; aborting.\n");
            break;
        }

        if (!validate_sensor_data(sensor_value)) {
            fprintf(stderr, "Invalid sensor data: %d\n", sensor_value);
            break;
        }

        char *payload = format_sensor_data(sensor_value);
        if (payload == NULL) {
            fprintf(stderr, "Failed to format sensor data; aborting.\n");
            break;
        }

        if (publish_sensor_data(client, MQTT_TOPIC, payload) != 0) {
            fprintf(stderr, "Failed to publish sensor data; aborting.\n");
            free(payload);
            break;
        }

        free(payload);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean up resources */
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 23

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "gpio23-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Main loop: toggle every 5 seconds */
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        val = val ? 0 : 1;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO 23 set to %d\n", val);
        fflush(stdout);

        /* Sleep 5 seconds, but wake early on signal */
        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define OUTPUT_PIN  27

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms max echo wait */
#define CYCLE_DELAY_US   100000  /* 0.1 s between readings */
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define SOUND_SPEED_CM_US 0.0343f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts;
    ts.tv_sec  = us / 1000000U;
    ts.tv_nsec = (long)(us % 1000000U) * 1000L;
    nanosleep(&ts, NULL);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *out = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    out  = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!trig || !echo || !out) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(out, "hcsr04-out", 0) < 0) {
        perror("gpiod_line_request_output(out)");
        goto cleanup;
    }

    while (g_running) {
        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig,0)");
            break;
        }
        sleep_us(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig,1)");
            break;
        }
        sleep_us(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig,0)");
            break;
        }

        /* Wait for echo rising edge */
        long long t0 = now_us();
        int val;
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (now_us() - t0 > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                goto cleanup;
            }
        } while (val == 0);

        long long echo_start = now_us();

        /* Wait for echo falling edge */
        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (now_us() - echo_start > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                goto cleanup;
            }
        } while (val == 1);

        long long echo_end = now_us();
        long long elapsed = echo_end - echo_start;

        float distance = (float)elapsed * SOUND_SPEED_CM_US / 2.0f;

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            fprintf(stderr, "Out-of-range reading: %.2f cm\n", distance);
            goto cleanup;
        }

        if (gpiod_line_set_value(out, 1) < 0) {
            perror("gpiod_line_set_value(out,1)");
            break;
        }
        sleep_us(10);
        if (gpiod_line_set_value(out, 0) < 0) {
            perror("gpiod_line_set_value(out,0)");
            break;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        sleep_us(CYCLE_DELAY_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (out)  gpiod_line_release(out);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
