#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "gpio17-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Main loop: toggle every second */
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        if (gpiod_line_set_value(line, val ? 0 : 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO 17 set to %d\n", val ? 0 : 1);
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line and close the chip */
    if (line) {
        gpiod_line_release(line);
    }
