        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_TOPIC "sensor/data"
#define GPIO_PIN 4
#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int publish_sensor_data(MQTTClient client, int sensor_value) {
    char payload[16];
    int rc;

    snprintf(payload, sizeof(payload), "%d", sensor_value);

    rc = MQTTClient_publish(client, MQTT_TOPIC, strlen(payload), payload, 0, 0, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_value = read_sensor_data(GPIO_PIN);
        if (sensor_value < 0) {
            break;
        }

        if (publish_sensor_data(client, sensor_value) != 0) {
            break;
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define STEP_US 5000000

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or permissions)\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (signal(SIGTERM, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int value = 0;
    int increment = 1;

    while (running) {
        if (gpioPWM(PWM_PIN, value) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("GPIO %d PWM duty cycle: %d/%d\n", PWM_PIN, value, PWM_RANGE);
        fflush(stdout);

        value += increment;
        if (value >= PWM_RANGE) {
            value = PWM_RANGE - 1;
            increment = -1;
        } else if (value <= 0) {
            value = 1;
            increment = 1;
        }

        usleep(STEP_US);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

/*
 * HC-SR04 ultrasonic distance measurement using libgpiod.
 *
 * Wiring (BCM numbering):
 *   VCC  -> 5V  (pin 2 or 4)
 *   GND  -> GND (pin 6)
 *   TRIG -> GPIO 23 (pin 16)
 *   ECHO -> GPIO 24 (pin 18) via voltage divider (3.3 V max on GPIO)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 *
 * Run:
 *   ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define TRIG_PIN  23
#define ECHO_PIN  24

#define TRIG_PULSE_US  10
#define ECHO_TIMEOUT_US 30000   /* 30 ms (~5 m round trip) */
#define LOOP_DELAY_US   200000 /* 0.2 s */
#define MAX_DISTANCE_CM 400.0
#define MIN_DISTANCE_CM 2.0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts;
    ts.tv_sec  = us / 1000000U;
    ts.tv_nsec = (long)(us % 1000000U) * 1000L;
    nanosleep(&ts, NULL);
}

/*
 * Measure distance in cm. Returns -1.0 on timeout or error.
 */
static float measure_distance(struct gpiod_line *trig, struct gpiod_line *echo)
{
    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIG low: %s\n", strerror(errno));
        return -1.0f;
    }
    sleep_us(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIG high: %s\n", strerror(errno));
        return -1.0f;
    }
    sleep_us(TRIG_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIG low: %s\n", strerror(errno));
        return -1.0f;
    }

    /* Wait for echo rising edge */
    long long t0 = now_us();
    int val;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read ECHO: %s\n", strerror(errno));
            return -1.0f;
        }
        if (now_us() - t0 > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    } while (val == 0);

    long long rise = now_us();

    /* Wait for echo falling edge */
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Error: failed to read ECHO: %s\n", strerror(errno));
            return -1.0f;
        }
        if (now_us() - rise > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    } while (val == 1);

    long long fall = now_us();
    long long pulse_us = fall - rise;

    /* Speed of sound ~343 m/s => 0.0343 cm/us; round trip => /2 */
    float distance = (float)pulse_us * 0.0343f / 2.0f;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        fprintf(stderr, "Error: failed to get TRIG line %d: %s\n", TRIG_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Error: failed to get ECHO line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request TRIG as output, initial value low */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Error: failed to request TRIG as output: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request ECHO as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Error: failed to request ECHO as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance(trig, echo);
        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Distance: out of range\n");
        }
        fflush(stdout);

        /* Sleep in small increments so signals are caught promptly */
        unsigned int remaining = LOOP_DELAY_US;
        while (remaining > 0 && g_running) {
            unsigned int chunk = remaining > 100000U ? 100000U : remaining;
            sleep_us(chunk);
            remaining -= chunk;
        }
    }

    printf("\nExiting cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23

#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure pins as hardware-PWM outputs */
    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_4, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int values[4] = {0, 0, 0, 0};

    while (running) {
        for (int i = 0; i < 4; i++) {
            values[i] = (values[i] + 1) % (PWM_RANGE + 1);
            if (gpioPWM(PWM_PIN_1 + i, values[i]) != 0) {
                fprintf(stderr, "Failed to set PWM on pin %d\n", PWM_PIN_1 + i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }

        printf("PWM: %d %d %d %d\n", values[0], values[1], values[2], values[3]);
        fflush(stdout);

        usleep(100000); /* 0.1 s */
    }

    /* Clean shutdown: turn off all PWM outputs */
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID      "rpi_sensor_publisher"
#define MQTT_TOPIC          "sensor/data"
#define MQTT_QOS            0
#define MQTT_KEEPALIVE      60
#define SENSOR_READING_INTERVAL 5
#define SENSOR_TIMEOUT_MS   1000
#define GPIO_PIN            4

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_sensor_data(int gpio_pin, int *out_value) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    *out_value = value;
    return 0;
}

static bool validate_sensor_data(int sensor_value) {
    return (sensor_value >= 0 && sensor_value <= 1);
}

static char *format_sensor_data(int sensor_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char *payload = malloc(64);
    if (payload == NULL) {
        perror("Failed to allocate memory for payload");
        return NULL;
    }
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(payload, 64, "%s,%d", timestamp, sensor_value);
    return payload;
}

static int publish_sensor_data(MQTTClient client, const char *payload) {
    MQTTClient_message message;
    MQTTClient_deliveryToken token;
    int rc;

    message.payload = (void *)payload;
    message.payloadlen = (int)strlen(payload);
    message.qos = MQTT_QOS;
    message.retained = 0;
    message.properties = NULL;

    rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &message, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    printf("Published: %s\n", payload);
    return 0;
}

int main(void) {
    MQTTClient client;
    int rc;
    int sensor_value;
    char *payload = NULL;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO pin %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO pin %d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID,
                           MQTTCLIENT_PERSISTENCE_NONE, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClient_connect(client, NULL);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Connected to MQTT broker at %s\n", MQTT_BROKER_ADDRESS);

    while (g_running) {
        if (read_sensor_data(GPIO_PIN, &sensor_value) != 0) {
            fprintf(stderr, "Sensor read failed; aborting.\n");
            break;
        }

        if (!validate_sensor_data(sensor_value)) {
            fprintf(stderr, "Invalid sensor data: %d\n", sensor_value);
            break;
        }

        payload = format_sensor_data(sensor_value);
        if (payload == NULL) {
            fprintf(stderr, "Failed to format sensor data; aborting.\n");
            break;
        }

        if (publish_sensor_data(client, payload) != 0) {
            fprintf(stderr, "Failed to publish sensor data; aborting.\n");
            free(payload);
            break;
        }

        free(payload);
        payload = NULL;

        for (int i = 0; i < SENSOR_READING_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();

    printf("Clean shutdown complete.\n");
    return EXIT_SUCCESS;
}

