void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

int ads1115_init(int handle) {
    int rc = i2cWriteWordData(handle, ADS1115_REG_CONFIG, ADS1115_CONFIG_VALUE);
    if (rc < 0) {
        fprintf(stderr, "Error writing ADS1115 config: %s\n", pigpio_error(rc));
        return -1;
    }
    return 0;
}

int ads1115_read(int handle, float *value) {
    int rc = i2cReadWordData(handle, ADS1115_REG_CONVERSION);
    if (rc < 0) {
        fprintf(stderr, "Error reading ADS1115 conversion: %s\n", pigpio_error(rc));
        return -1;
    }
    int16_t raw = (int16_t)rc;
    *value = (float)raw * 4.096f / 32768.0f;
    return 0;
}

int mqtt_connect(MQTTClient *client, const char *broker_address, const char *client_id, const char *topic) {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    MQTTClient_create(client, broker_address, client_id, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    rc = MQTTClient_connect(*client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(client);
        return -1;
    }
    return 0;
}

int mqtt_publish(MQTTClient *client, const char *topic, const char *payload) {
    int rc = MQTTClient_publish(client, topic, (int)strlen(payload), payload, 0, 0);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(ADS1115_I2C_BUS, ADS1115_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return 1;
    }

    if (ads1115_init(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (mqtt_connect(&mqtt_client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTT_TOPIC) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    strncpy(mqtt_topic, MQTT_TOPIC, sizeof(mqtt_topic) - 1);
    mqtt_topic[sizeof(mqtt_topic) - 1] = '\0';

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    for (int i = 0; i < NUM_READINGS && running; i++) {
        float sensor_value;
        if (ads1115_read(i2c_handle, &sensor_value) == 0) {
            char payload[64];
            snprintf(payload, sizeof(payload), "%.3f", sensor_value);
            if (mqtt_publish(&mqtt_client, mqtt_topic, payload) != 0) {
