    char buffer[READ_SIZE];
    ssize_t bytes_read;

    while (!g_stop) {
        bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s\n", buffer);
            fflush(stdout);
        } else if (bytes_read < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                continue;
            }
            perror("read");
            break;
        }
    }

    if (close(fd) != 0) {
        perror("close");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define SAMPLE_PERIOD_US 100000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    usleep(100000);

    while (g_running) {
        int16_t ax, ay, az;
        if (read_accel(fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Error reading accelerometer: %s\n", strerror(errno));
            break;
        }
        printf("X: %d, Y: %d, Z: %d\n", ax, ay, az);
        fflush(stdout);
        usleep(SAMPLE_PERIOD_US);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CALIB_26 0xE1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_read_calibration(int fd, bmp280_calib_t *cal) {
    uint8_t buf[26];
    if (i2c_read_reg(fd, BMP280_REG_CALIB_00, buf, 26) < 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[1] << 8 | buf[0]);
    cal->dig_T2 = (int16_t)(buf[3] << 8 | buf[2]);
    cal->dig_T3 = (int16_t)(buf[5] << 8 | buf[4]);
    cal->dig_P1 = (uint16_t)(buf[7] << 8 | buf[6]);
    cal->dig_P2 = (int16_t)(buf[9] << 8 | buf[8]);
    cal->dig_P3 = (int16_t)(buf[11] << 8 | buf[10]);
    cal->dig_P4 = (int16_t)(buf[13] << 8 | buf[12]);
    cal->dig_P5 = (int16_t)(buf[15] << 8 | buf[14]);
    cal->dig_P6 = (int16_t)(buf[17] << 8 | buf[16]);
    cal->dig_P7 = (int16_t)(buf[19] << 8 | buf[18]);
    cal->dig_P8 = (int16_t)(buf[21] << 8 | buf[20]);
    cal->dig_P9 = (int16_t)(buf[23] << 8 | buf[22]);
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) return -1;
    if (id != 0x58) {
        fprintf(stderr, "Error: BMP280 not found (ID=0x%02X, expected 0x58)\n", id);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_RESET, 0xB6) < 0) return -1;
    usleep(2000);
    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg(fd, BMP280_REG_STATUS, &status, 1) < 0) return -1;
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t buf[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, buf, 6) < 0) return -1;
    *raw_p = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    *raw_t = (int32_t)((buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4));
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_t, const bmp280_calib_t *cal, int32_t *t_fine) {
    double v1 = ((double)raw_t / 16384.0 - (double)cal->dig_T1 / 1024.0) * (double)cal->dig_T2;
    double v2 = ((double)raw_t / 131072.0 - (double)cal->dig_T1 / 8192.0) *
                ((double)raw_t / 131072.0 - (double)cal->dig_T1 / 8192.0) * (double)cal->dig_T3;
    *t_fine = (int32_t)(v1 + v2);
    return (v1 + v2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_p, const bmp280_calib_t *cal, int32_t t_fine) {
    double v1 = (double)t_fine / 2.0 - 64000.0;
    double v2 = v1 * v1 * (double)cal->dig_P6 / 32768.0;
    v2 = v2 + v1 * (double)cal->dig_P5 * 2.0;
    v2 = v2 / 4.0 + (double)cal->dig_P4 * 65536.0;
    v1 = ((double)cal->dig_P3 * v1 * v1 / 524288.0 + (double)cal->dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * (double)cal->dig_P1;
    if (v1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_p;
    p = (p - v2 / 4096.0) * 6250.0 / v1;
    v1 = (double)cal->dig_P9 * p * p / 2147483648.0;
    v2 = p * (double)cal->dig_P8 / 32768.0;
    p = p + (v1 + v2 + (double)cal->dig_P7) / 16.0;
    return p;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }
    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "Error initializing BMP280: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    bmp280_calib_t cal;
    if (bmp280_read_calibration(fd, &cal) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    printf("BMP280 initialized. Reading every 5 seconds. Press Ctrl+C to exit.\n");
    while (g_running) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(fd, &raw_t, &raw_p) < 0) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            break;
        }
        int32_t t_fine;
        double temp = bmp280_compensate_temp(raw_t, &cal, &t_fine);
        double press = bmp280_compensate_press(raw_p, &cal, t_fine);
        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp, press);
        for (int i = 0; i < 5 && g_running; i++) sleep(1);
    }
    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 4
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or permissions)\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int duty = 500;
    if (gpioPWM(PWM_PIN, duty) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d: range=%d, freq=%d Hz, duty=%d\n",
           PWM_PIN, PWM_RANGE, PWM_FREQ, duty);

    /* Allow the PWM line to settle, then clean up. */
    gpioDelay(100000); /* 100 ms */

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_13 13

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    int values[3] = {1, 0, 1};
    int pins[3] = {GPIO_5, GPIO_6, GPIO_13};
    int i;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], "gpio_control", values[i]) < 0) {
            fprintf(stderr, "Failed to request output on line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < 3; i++) {
        printf("GPIO %d set to %d\n", pins[i], values[i]);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"
#define MQTT_TOPIC "sensor/data"
#define GPIO_PIN 4
#define SAMPLE_INTERVAL_MS 1000

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main() {
    int rc;
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    char payload[256];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_value = gpioRead(GPIO_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", GPIO_PIN);
            break;
        }

        snprintf(payload, sizeof(payload), "Sensor Value: %d", sensor_value);
        if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, NULL, payload, strlen(payload), 0, 0)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
            break;
        }

        printf("Published: %s\n", payload);
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
    return EXIT_SUCCESS;
}

