#include <signal.h>

#define PWM_PIN 18

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, sig_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(PWM_PIN, 128) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM set on GPIO %d (50%% duty cycle)\n", PWM_PIN);

    /* Allow the PWM to be observed before clean shutdown */
    gpioDelay(1000000); /* 1 second */

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("PWM stopped and pigpio terminated\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 27

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "gpio27-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Main loop: toggle every 2 seconds */
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        val = val ? 0 : 1;
        if (gpiod_line_set_value(line, val) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, val);
        fflush(stdout);

        /* Sleep 2 seconds, but wake early on signal */
        for (int i = 0; i < 20 && running; i++) {
            usleep(100000); /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

