#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_17 17
#define PWM_PIN_18 18
#define PWM_PIN_27 27
#define PWM_RANGE 255
#define PWM_FREQ 1000
#define DELAY_US 500000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers.\n");
    }

    /* Configure all three pins as hardware-PWM outputs */
    int pins[] = {PWM_PIN_17, PWM_PIN_18, PWM_PIN_27};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int state = 0;
    while (running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioPWM(pins[i], state) != 0) {
                fprintf(stderr, "Error: failed to set PWM on GPIO %d.\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("GPIO %d, %d, %d -> PWM %d\n", PWM_PIN_17, PWM_PIN_18, PWM_PIN_27, state);
        fflush(stdout);
        state = (state + 1) % (PWM_RANGE + 1);
        usleep(DELAY_US);
    }

    /* Clean shutdown: turn off PWM and release pigpio */
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_TIMINGS 85

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_us) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        usleep(1);
        elapsed++;
        if (elapsed >= timeout_us) return elapsed;
    }
    return elapsed;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int timings[MAX_TIMINGS];
    int idx = 0;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    usleep(1000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    usleep(40);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, 1000) > 1000) return -1;
    if (wait_for_level(line, 1, 1000) > 1000) return -1;
    if (wait_for_level(line, 0, 1000) > 1000) return -1;

    for (int i = 0; i < MAX_TIMINGS && idx < 40; i++) {
        int low = wait_for_level(line, 1, 1000);
        if (low > 1000) return -1;
        int high = wait_for_level(line, 0, 1000);
        if (high > 1000) return -1;
        timings[idx++] = low + high;
    }

    if (idx < 40) return -1;

    for (int i = 0; i < 40; i++) {
        int threshold = (timings[i] > 50) ? 1 : 0;
        data[i / 8] <<= 1;
        data[i / 8] |= threshold;
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (data[4] != checksum) return -1;

    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];

    *hum = (float)raw_h / 10.0f;
    if (raw_t & 0x8000) {
        *temp = -((float)(raw_t & 0x7FFF)) / 10.0f;
    } else {
        *temp = (float)raw_t / 10.0f;
    }

    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    float temp = 0.0f, hum = 0.0f;
    int ret = read_dht22(line, &temp, &hum);

    if (ret == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
    } else {
        fprintf(stderr, "Failed to read DHT22 sensor\n");
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return (ret == 0) ? 0 : 1;
}

