#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "mcp3008_sensor"
#define MQTT_TOPIC "sensor/data"
#define MCP3008_CHANNEL 0
#define SAMPLE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    int handle = gpioInitialise();
    if (handle < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %d\n", handle);
        return -1;
    }

    int result = -1;
    try {
        gpioSetMode(0, PI_OUTPUT);
        gpioSetMode(1, PI_OUTPUT);
        gpioSetMode(2, PI_INPUT);

        gpioWrite(0, (channel & 0x01));
        gpioWrite(1, (channel & 0x02) >> 1);
        gpioWrite(2, (channel & 0x04) >> 2);

        gpioDelay(1000);

        int adc_value = 0;
        for (int i = 0; i < 8; i++) {
            gpioSetMode(2, PI_OUTPUT);
            gpioWrite(2, 0);
            gpioDelay(1);
            gpioSetMode(2, PI_INPUT);
            gpioDelay(1);
            adc_value |= (gpioRead(2) << i);
        }

        result = adc_value;
    } catch (...) {
        fprintf(stderr, "Error: Exception occurred during MCP3008 read\n");
        result = -1;
    }

    gpioTerminate();
    return result;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    MQTTClient client;
    int rc;

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);
    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return 1;
    }

    int adc_value = read_mcp3008(MCP3008_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Error: Failed to read ADC value\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return 1;
    }

    char payload[20];
    snprintf(payload, sizeof(payload), "%d", adc_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to publish message: %s\n", MQTTClient_strerror(rc));
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return 1;
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    return 0;
}

/*
 * capture.c - Capture a single image from the Raspberry Pi camera module
 * using the linux-v4l2 stack (struct v4l2_buffer, VIDIOC_REQBUFS, etc.).
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture capture.c
 * Run:    ./capture [filename]
 *
 * The default filename is "capture.jpg".
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(int argc, char *argv[])
{
    const char *dev_name = "/dev/video0";
    const char *filename = (argc > 1) ? argv[1] : "capture.jpg";
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    void *buffer_start = NULL;
    size_t buffer_length = 0;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    CLEAR(sa);
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(dev_name, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Cannot open '%s': %s\n", dev_name, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", dev_name);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", dev_name);
        goto cleanup;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_JPEG) {
        fprintf(stderr, "Device does not support JPEG output\n");
        goto cleanup;
    }

    CLEAR(req);
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        goto cleanup;
    }

    CLEAR(buf);
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    buffer_length = buf.length;
    buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        buffer_start = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        goto cleanup;
    }

    if (g_stop) {
        fprintf(stderr, "Interrupted before capture\n");
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Cannot open '%s' for writing: %s\n", filename, strerror(errno));
        goto cleanup;
    }

    size_t written = fwrite(buffer_start, 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        fprintf(stderr, "Short write to '%s': %s\n", filename, strerror(errno));
        fclose(fp);
        fp = NULL;
        goto cleanup;
    }

    if (fclose(fp) == EOF) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        fp = NULL;
        goto cleanup;
    }
    fp = NULL;

    printf("Captured %zu bytes to %s\n", buf.bytesused, filename);

    ret = EXIT_SUCCESS;

cleanup:
    if (buffer_start && buffer_start != MAP_FAILED) {
        munmap(buffer_start, buffer_length);
    }
    if (fd != -1) {
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
            perror("VIDIOC_STREAMOFF");
        }
        close(fd);
    }
    if (fp) {
        fclose(fp);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
