#include <pigpio.h>

#define NUM_PINS 6
static const int pins[NUM_PINS] = {4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("GPIO 4,5,6,7,8,9 PWM set to 128/255\n");
    fflush(stdout);

    while (running) {
        gpioDelay(100000);
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define NUM_CYCLES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL, *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line17 || !line18) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, "gpio-cycle", 0) < 0) {
        perror("gpiod_line_request_output line17");
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, "gpio-cycle", 0) < 0) {
        perror("gpiod_line_request_output line18");
        goto cleanup;
    }

    for (int cycle = 0; cycle < NUM_CYCLES && running; cycle++) {
        /* GPIO 17 high, GPIO 18 low */
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value line17 high");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 0) < 0) {
            perror("gpiod_line_set_value line18 low");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17 HIGH, GPIO 18 LOW\n", cycle + 1);
        fflush(stdout);
        sleep(1);

        /* GPIO 17 low, GPIO 18 high */
        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value line17 low");
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 1) < 0) {
            perror("gpiod_line_set_value line18 high");
            goto cleanup;
        }
        printf("Cycle %d: GPIO 17 LOW, GPIO 18 HIGH\n", cycle + 1);
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left low before release */
    if (line17) gpiod_line_set_value(line17, 0);
    if (line18) gpiod_line_set_value(line18, 0);
    if (line17) gpiod_line_release(line17);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

