#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27
#define DELAY_MS 500

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t value) {
    if (write(fd, &value, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void display_value(int fd, int value) {
    if (value < 0 || value > 255) {
        fprintf(stderr, "Error: Value out of range (0-255): %d\n", value);
        return;
    }
    if (i2c_write_byte(fd, (uint8_t)value) != 0) {
        fprintf(stderr, "Failed to display value: %d\n", value);
    }
}

int main(void) {
    int fd = -1;
    int ret = 1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return 1;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", PCF8574_ADDR, strerror(errno));
        goto cleanup;
    }

    for (int i = 0; i < 256 && running; i++) {
        display_value(fd, i);
        usleep(DELAY_MS * 1000);
    }

    ret = 0;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

