/*
 * HC-SR04 ultrasonic distance sensor reader using libgpiod.
 *
 * Wiring (BCM numbering):
 *   VCC  -> 5V  (pin 2 or 4)
 *   GND  -> GND (pin 6)
 *   TRIG -> GPIO17 (pin 11)
 *   ECHO -> GPIO18 (pin 12)  [3.3 V safe; use divider if 5 V]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 *
 * Run:
 *   ./hcsr04
 */

#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define TRIG_PIN 17
#define ECHO_PIN 18
#define CONSUMER "hcsr04"

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static long long now_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL;
}

/*
 * Measure the ECHO pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout or error.
 */
static long measure_pulse(struct gpiod_line *trig, struct gpiod_line *echo)
{
    const long timeout_us = 30000;   /* 30 ms max echo wait */
    const long settle_us  = 1000;    /* 1 ms settle after trigger */

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(5);

    /* 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "set trigger high failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "set trigger low failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge */
    long long t0 = now_ms();
    int val;
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "read echo failed: %s\n", strerror(errno));
            return -1;
        }
        if (now_ms() - t0 > timeout_us) {
            fprintf(stderr, "timeout waiting for echo rising edge\n");
            return -1;
        }
    } while (val == 0);

    long long rise = now_ms();

    /* Wait for echo falling edge */
    do {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "read echo failed: %s\n", strerror(errno));
            return -1;
        }
        if (now_ms() - rise > timeout_us) {
            fprintf(stderr, "timeout waiting for echo falling edge\n");
            return -1;
        }
    } while (val == 1);

    long long fall = now_ms();
    return (long)(fall - rise) * 1000;   /* us */
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int rc = EXIT_FAILURE;

    /* Signal handling for clean exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3/4/5) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get GPIO%d: %s\n", TRIG_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get GPIO%d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO%d as output: %s\n",
                TRIG_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        fprintf(stderr, "Failed to request GPIO%d as input: %s\n",
                ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ready. TRIG=GPIO%d, ECHO=GPIO%d. Press Ctrl+C to exit.\n",
           TRIG_PIN, ECHO_PIN);
    fflush(stdout);

    while (g_running) {
        long pulse_us = measure_pulse(trig, echo);
        if (pulse_us < 0) {
            fprintf(stderr, "Sensor read failed or sensor absent.\n");
            goto cleanup;
        }

        /* distance = (pulse_us / 2) / 29.1  (cm) */
        float distance_cm = (float)pulse_us / 58.2f;

        printf("Distance: %.2f cm\n", distance_cm);
        fflush(stdout);

        sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) {
        gpiod_line_release(trig);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (rc == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 1000 for all four pins */
    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], 1000) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < 1000 && running; ++i) {
            if (gpioPWM(PWM_PIN_1, i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_1);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (gpioPWM(PWM_PIN_2, 1000 - i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_2);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (gpioPWM(PWM_PIN_3, i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_3);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (gpioPWM(PWM_PIN_4, 1000 - i) != 0) {
                fprintf(stderr, "PWM write failed on GPIO %d\n", PWM_PIN_4);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM: %d, %d, %d, %d\n", i, 1000 - i, i, 1000 - i);
            fflush(stdout);
            gpioDelay(1000); /* 1 ms per step */
        }
        gpioDelay(1000000); /* 1 s between sweeps */
    }

    /* Clean shutdown: set all PWM outputs to 0 */
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define CAPTURE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    int fd = -1;
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        fprintf(stderr, "VIDIOC_QUERYCAP failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;
    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    void *buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        munmap(buffer_start, buf.length);
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = CAPTURE_INTERVAL_US;
        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select failed: %s\n", strerror(errno));
            break;
        }
        if (r == 0) continue;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            break;
        }

        FILE *fp = fopen("image.jpg", "wb");
        if (fp == NULL) {
            fprintf(stderr, "Error opening image.jpg: %s\n", strerror(errno));
        } else {
            size_t bytes_written = fwrite(buffer_start, 1, buf.bytesused, fp);
            if (bytes_written != buf.bytesused) {
                fprintf(stderr, "Short write to image.jpg\n");
            }
            fclose(fp);
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
            break;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
    }
    munmap(buffer_start, buf.length);
    close(fd);
    return EXIT_SUCCESS;
}

#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i <= PWM_RANGE && running; i++) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle %d\n", i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d\n", i);
            fflush(stdout);
            gpioDelay(10000);
        }
        for (int i = PWM_RANGE; i >= 0 && running; i--) {
            if (gpioPWM(PWM_PIN, i) != 0) {
                fprintf(stderr, "Failed to set PWM duty cycle %d\n", i);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("PWM duty cycle: %d\n", i);
            fflush(stdout);
            gpioDelay(10000);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x27
#define PCF8574_MAX_RETRIES 3
#define PCF8574_RETRY_DELAY_US 10000

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int i2c_write_byte(int fd, uint8_t value) {
    if (write(fd, &value, 1) != 1) {
        return -1;
    }
    return 0;
}

static int pcf8574_write(int fd, uint8_t value) {
    for (int attempt = 0; attempt < PCF8574_MAX_RETRIES; attempt++) {
        if (i2c_write_byte(fd, value) == 0) {
            return 0;
        }
        if (g_stop) {
            return -1;
        }
        usleep(PCF8574_RETRY_DELAY_US);
    }
    return -1;
}

static void display_number(int fd, int number) {
    if (number < 0 || number > 9999) {
        fprintf(stderr, "Error: Number out of range (0-9999).\n");
        return;
    }

    uint8_t digits[4];
    digits[0] = (number / 1000) % 10;
    digits[1] = (number / 100) % 10;
    digits[2] = (number / 10) % 10;
    digits[3] = number % 10;

    uint8_t patterns[] = {
        0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F
    };

    uint8_t display_value = 0;
    for (int i = 0; i < 4; i++) {
        display_value |= (patterns[digits[i]] << (i * 8));
    }

    if (pcf8574_write(fd, display_value) != 0) {
        fprintf(stderr, "Error: Failed to write to PCF8574.\n");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    int number = 1234;
    display_number(fd, number);

    if (close(fd) < 0) {
        perror("Error closing I2C bus");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

#include <gpiod.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 16

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initially low */
    if (gpiod_line_request_output(line, "gpio16_out", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Set the line high */
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value");
        goto cleanup;
    }

    printf("GPIO 16 set to HIGH\n");
    fflush(stdout);

