#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 23
#define PWM_PIN_3 24
#define PWM_RANGE 255
#define STEP_US 100000  /* 0.1 s */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

int main(void) {
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialise pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or not running?)\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM pins --- */
    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int v1 = 0, v2 = 0, v3 = 0;

    /* --- Main loop --- */
    while (g_running) {
        v1 = (v1 + 1) % (PWM_RANGE + 1);
        v2 = (v2 + 1) % (PWM_RANGE + 1);
        v3 = (v3 + 1) % (PWM_RANGE + 1);

        if (gpioPWM(PWM_PIN_1, v1) != 0) {
            fprintf(stderr, "gpioPWM failed on GPIO %d\n", PWM_PIN_1);
            break;
        }
        if (gpioPWM(PWM_PIN_2, v2) != 0) {
            fprintf(stderr, "gpioPWM failed on GPIO %d\n", PWM_PIN_2);
            break;
        }
        if (gpioPWM(PWM_PIN_3, v3) != 0) {
            fprintf(stderr, "gpioPWM failed on GPIO %d\n", PWM_PIN_3);
            break;
        }

        printf("PWM: GPIO%d=%d, GPIO%d=%d, GPIO%d=%d\n",
               PWM_PIN_1, v1, PWM_PIN_2, v2, PWM_PIN_3, v3);
        fflush(stdout);

        usleep(STEP_US);
    }

    /* --- Clean shutdown: turn off PWM and release pigpio --- */
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

/*
 * HC-SR04 ultrasonic distance measurement using libgpiod.
 *
 * Wiring (BCM numbering):
 *   VCC  -> 5V  (pin 2 or 4)
 *   GND  -> GND (pin 6)
 *   TRIG -> GPIO17 (pin 11)
 *   ECHO -> GPIO18 (pin 12)  [use a voltage divider if your Pi is 5V]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 *
 * Run:
 *   ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define TRIG_PIN  17
#define ECHO_PIN  18

#define SPEED_OF_SOUND_CM_S  34300.0
#define MAX_DISTANCE_CM      400.0
#define MIN_DISTANCE_CM      2.0

#define ECHO_TIMEOUT_US      30000   /* 30 ms (~5 m round trip) */
#define TRIG_PULSE_US        10      /* 10 us trigger pulse */
#define SETTLE_US            100000  /* 100 ms settle after trigger */

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

static long long now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts;
    ts.tv_sec  = us / 1000000U;
    ts.tv_nsec = (long)(us % 1000000U) * 1000L;
    nanosleep(&ts, NULL);
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns >= 0 on success, -1 on timeout, -2 on read error.
 */
static long measure_echo(struct gpiod_line *trig, struct gpiod_line *echo)
{
    long long t0, t;

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        return -2;
    }
    sleep_us(5);

    /* Send 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        return -2;
    }
    sleep_us(TRIG_PULSE_US);
    if (gpiod_line_set_value(trig, 0) < 0) {
        return -2;
    }

    /* Wait for echo rising edge */
    t0 = now_us();
    for (;;) {
        int v = gpiod_line_get_value(echo);
        if (v < 0) {
            return -2;
        }
        if (v == 1) {
            break;
        }
        if (now_us() - t0 > ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    /* Measure echo high duration */
    t0 = now_us();
    for (;;) {
        int v = gpiod_line_get_value(echo);
        if (v < 0) {
            return -2;
        }
        if (v == 0) {
            break;
        }
        if (now_us() - t0 > ECHO_TIMEOUT_US) {
            return -1;
        }
    }

    return (long)(now_us() - t0);
}

static float calc_distance(long pulse_us)
{
    float dist = (float)pulse_us * SPEED_OF_SOUND_CM_S / 2000000.0f;
    if (dist < MIN_DISTANCE_CM) dist = MIN_DISTANCE_CM;
    if (dist > MAX_DISTANCE_CM) dist = MAX_DISTANCE_CM;
    return dist;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 3/4/5) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIG_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request trigger as output, initial value low */
    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request TRIG line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request ECHO line: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Allow sensor to settle */
    sleep_us(SETTLE_US);

    long pulse = measure_echo(trig, echo);
    if (pulse < 0) {
        if (pulse == -1) {
            fprintf(stderr, "Error: Echo timeout - sensor not responding or no object in range.\n");
        } else {
            fprintf(stderr, "Error: GPIO read/write failure: %s\n", strerror(errno));
        }
        goto cleanup;
    }

    float distance = calc_distance(pulse);
    printf("Distance: %.2f cm\n", distance);
    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 23
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 23 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio23-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d initialized as output (LOW).\n", GPIO_LINE_OFFSET);

    /* Main loop: toggle every 5 seconds */
    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value HIGH");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);

        if (!running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value LOW");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("GPIO %d released. Exiting.\n", GPIO_LINE_OFFSET);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_REG_ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_read_reg8(fd, MPU6050_REG_PWR_MGMT_1, NULL) < 0) {
        fprintf(stderr, "MPU6050 not detected at 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    usleep(100000);

    while (g_running) {
        int16_t ax, ay, az;
        if (read_accel(fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Error reading accelerometer: %s\n", strerror(errno));
            break;
        }
        printf("X: %d, Y: %d, Z: %d\n", ax, ay, az);
        fflush(stdout);
        usleep(100000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 3
#define CYCLES 3
#define DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    unsigned int pins[NUM_PINS] = {2, 3, 17};
    int i, cycle;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-cycle", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (cycle = 0; cycle < CYCLES && running; cycle++) {
        for (i = 0; i < NUM_PINS && running; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("Cycle %d: GPIO %u set HIGH\n", cycle + 1, pins[i]);
            fflush(stdout);
            sleep(DELAY_SEC);
            if (!running) break;
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            printf("Cycle %d: GPIO %u set LOW\n", cycle + 1, pins[i]);
            fflush(stdout);
            sleep(DELAY_SEC);
        }
    }

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip)
        gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

