    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = { msb, lsb };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *data, size_t len) {
    ssize_t n = read(fd, data, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sht31(int fd, float *temperature, float *humidity) {
    if (i2c_write_cmd(fd, MEAS_CMD_MSB, MEAS_CMD_LSB) < 0) {
        return -1;
    }

    usleep(MEAS_DELAY_MS * 1000);

    uint8_t data[6];
    if (i2c_read_data(fd, data, 6) < 0) {
        return -1;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw  = (data[3] << 8) | data[4];

    if (temp_raw == 0x0000 || temp_raw == 0xFFFF || hum_raw == 0x0000 || hum_raw == 0xFFFF) {
        fprintf(stderr, "Invalid sensor data (stuck at extreme)\n");
        return -1;
    }

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity    = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SHT31_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    while (g_running) {
        float temperature, humidity;
        if (read_sht31(fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        for (int i = 0; i < LOOP_DELAY_S && g_running; i++) {
            sleep(1);
        }
    }

    close(fd);
    return 0;
}

