#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_PINS 4
static const int pins[NUM_PINS] = {17, 18, 22, 27};

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (device absent or not running?)\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("GPIO %d: PWM 128\n", pins[i]);
    }

    if (g_stop) {
        for (int i = 0; i < NUM_PINS; i++) {
            gpioPWM(pins[i], 0);
        }
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

