#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_2 2
#define GPIO_17 17
#define INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line17 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("gpiod_chip_get_line(2)");
        goto cleanup;
    }
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value 0 */
    if (gpiod_line_request_output(line2, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output(2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line17, "gpio-toggle", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 60 seconds */
    while (running) {
        int val2 = gpiod_line_get_value(line2);
        int val17 = gpiod_line_get_value(line17);

        if (val2 < 0 || val17 < 0) {
            fprintf(stderr, "Error reading line values\n");
            goto cleanup;
        }

        /* Toggle each line */
        if (gpiod_line_set_value(line2, val2 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(2)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line17, val17 ? 0 : 1) < 0) {
            perror("gpiod_line_set_value(17)");
            goto cleanup;
        }

        printf("GPIO 2: %d, GPIO 17: %d\n", val2, val17);
        fflush(stdout);

        /* Sleep 60 seconds, but wake early on signal */
        for (int i = 0; i < INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip */
    if (line2) gpiod_line_release(line2);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);

    return ret;
}

