#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define NUM_CYCLES 3
#define CYCLE_DELAY_US 5000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CYCLES && g_running; i++) {
        if (gpioWrite(GPIO_PIN, 1) != 0) {
            fprintf(stderr, "Error: failed to write HIGH to GPIO %d.\n", GPIO_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        gpioDelay(CYCLE_DELAY_US);

        if (gpioWrite(GPIO_PIN, 0) != 0) {
            fprintf(stderr, "Error: failed to write LOW to GPIO %d.\n", GPIO_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        gpioDelay(CYCLE_DELAY_US);
    }

    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 27 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "gpio27-toggle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle every 2 seconds */
    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value HIGH");
            break;
        }
        printf("GPIO 27 set HIGH\n");
        fflush(stdout);

        sleep(2);

        if (!running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value LOW");
            break;
        }
        printf("GPIO 27 set LOW\n");
        fflush(stdout);

        sleep(2);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

