        goto cleanup;
    }
    if (gpiod_line_request_output(line17, "gpio-control", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    /* Set GPIO 8 high and GPIO 17 low */
    if (gpiod_line_set_value(line8, 1) < 0) {
        perror("gpiod_line_set_value (GPIO 8)");
        goto cleanup;
    }
    if (gpiod_line_set_value(line17, 0) < 0) {
        perror("gpiod_line_set_value (GPIO 17)");
        goto cleanup;
    }

    printf("GPIO 8 set to HIGH, GPIO 17 set to LOW\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line8) gpiod_line_release(line8);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

