#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_ID "28-00000xxxxxxx"  /* replace with your DS18B20 ROM */
#define W1_SLAVE_PATH W1_DEVICES_DIR "/" W1_SLAVE_ID
#define W1_TEMP_FILE "w1_slave"
#define NUM_READINGS 3
#define SLEEP_SECONDS 5

static volatile sig_atomic_t g_interrupted = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_interrupted = 1;
}

static int install_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    char path[512];
    char buffer[256];
    FILE *fp;
    int ret = -1;

    snprintf(path, sizeof(path), "%s/%s", W1_SLAVE_PATH, W1_TEMP_FILE);

    fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading first line from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (strstr(buffer, "YES") == NULL) {
        fprintf(stderr, "Sensor not ready or not present (CRC check failed)\n");
        fclose(fp);
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading second line from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Temperature data not found in %s\n", path);
        return -1;
    }

    long temp_reading = strtol(temp_str + 2, NULL, 10);
    if (temp_reading == 0 && errno == EINVAL) {
        fprintf(stderr, "Invalid temperature value in %s\n", path);
        return -1;
    }

    *temperature = (float)temp_reading / 1000.0f;
    ret = 0;
    return ret;
}

int main(void) {
    if (install_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_READINGS; i++) {
        if (g_interrupted) {
            fprintf(stderr, "\nInterrupted by signal. Exiting.\n");
            return EXIT_FAILURE;
        }

        float temperature;
        if (read_temperature(&temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
            return EXIT_FAILURE;
        }

        if (i < NUM_READINGS - 1) {
            sleep(SLEEP_SECONDS);
        }
    }

    return EXIT_SUCCESS;
}

