#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define OUTPUT_PIN 24

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define CYCLE_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *out = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    out = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!trig || !echo || !out) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(out, "hcsr04-out", 0) < 0) {
        perror("gpiod_line_request_output(out)");
        goto cleanup;
    }

    while (running) {
        long long t0 = now_us();

        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig,1)");
            break;
        }
        usleep(TRIGGER_PULSE_US);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig,0)");
            break;
        }

        long long wait_start = now_us();
        int val;
        while (running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 1) break;
            if (now_us() - wait_start > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo high\n");
                goto cleanup;
            }
            usleep(10);
        }

        long long echo_rise = now_us();
        while (running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(echo)");
                goto cleanup;
            }
            if (val == 0) break;
            if (now_us() - echo_rise > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo low\n");
                goto cleanup;
            }
            usleep(10);
        }
        long long echo_fall = now_us();

        long long elapsed = echo_fall - echo_rise;
        float distance = (float)elapsed / 58.0f;

        if (gpiod_line_set_value(out, (distance > 0.0f) ? 1 : 0) < 0) {
            perror("gpiod_line_set_value(out)");
            break;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        usleep(CYCLE_DELAY_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (out) gpiod_line_release(out);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define NUM_CYCLES 10

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value 0 */
    ret = gpiod_line_request_output(line, "gpio17-cycle", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Perform 10 cycles of toggling */
    for (int i = 0; i < NUM_CYCLES && running; i++) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value high");
            break;
        }
        printf("GPIO 17 set HIGH\n");
        fflush(stdout);
        usleep(500000); /* 0.5 s */

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value low");
            break;
        }
        printf("GPIO 17 set LOW\n");
        fflush(stdout);
        usleep(500000); /* 0.5 s */
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    if (!running) {
        printf("\nInterrupted. Exiting cleanly.\n");
    }

    return EXIT_SUCCESS;
}

