#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_4  4
#define PWM_PIN_17 17
#define PWM_PIN_18 18
#define PWM_RANGE  255
#define PWM_FREQ   1000
#define STEP_US    100000  /* 0.1 s */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_pwm_value(int pin, int value)
{
    if (value < 0 || value > PWM_RANGE) {
        fprintf(stderr, "Invalid PWM value %d for pin %d (range 0-%d)\n",
                value, pin, PWM_RANGE);
        return -1;
    }
    if (gpioPWM(pin, value) != 0) {
        fprintf(stderr, "gpioPWM failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[3] = {PWM_PIN_4, PWM_PIN_17, PWM_PIN_18};
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "gpioSetMode failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "gpioSetPWMrange failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ) != 0) {
            fprintf(stderr, "gpioSetPWMfrequency failed on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    int values[3] = {0, 0, 0};
    int step = 1;

    while (g_running) {
        for (int i = 0; i < 3; i++) {
            values[i] += step;
            if (values[i] >= PWM_RANGE) {
                values[i] = PWM_RANGE;
                step = -1;
            } else if (values[i] <= 0) {
                values[i] = 0;
                step = 1;
            }
            if (set_pwm_value(pins[i], values[i]) != 0) {
                fprintf(stderr, "PWM write failed on pin %d; aborting\n", pins[i]);
                goto cleanup;
            }
        }
        printf("Pin %d: %d, Pin %d: %d, Pin %d: %d\n",
               PWM_PIN_4, values[0],
               PWM_PIN_17, values[1],
               PWM_PIN_18, values[2]);
        fflush(stdout);
        gpioDelay(STEP_US);
    }

cleanup:
    for (int i = 0; i < 3; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

