#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define MAX_CYCLES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static int wait_for_level(struct gpiod_line *line, int level, unsigned int timeout_us) {
    unsigned int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!running) return -1;
        sleep_us(1);
        elapsed++;
        if (elapsed >= timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    gpiod_line_set_value(line, 1);
    sleep_us(500000);
    gpiod_line_set_value(line, 0);
    sleep_us(20000);
    gpiod_line_set_value(line, 1);
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, 100) < 0) return -1;
    if (wait_for_level(line, 1, 100) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(line, 0, 100) < 0) return -1;
        unsigned int high_us = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (!running) return -1;
            sleep_us(1);
            high_us++;
            if (high_us > 100) return -1;
        }
        if (high_us > 40) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    uint8_t checksum = data[0] + data[1] + data[2] + data[3];
    if (checksum != data[4]) return -1;

    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];

    *humidity = (float)raw_h / 10.0f;
    if (raw_t & 0x8000) {
        *temperature = -((float)(raw_t & 0x7FFF)) / 10.0f;
    } else {
        *temperature = (float)raw_t / 10.0f;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temperature, humidity;
    int cycles = 0;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running && cycles < MAX_CYCLES) {
        if (read_dht22(line, &temperature, &humidity) == 0) {
            printf("Cycle %d: Temperature = %.1f C, Humidity = %.1f %%\n", cycles + 1, temperature, humidity);
            fflush(stdout);
        } else {
            fprintf(stderr, "Cycle %d: Failed to read DHT22 sensor\n", cycles + 1);
        }
        cycles++;
        sleep_us(2000000);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

