#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

#define PWM_PIN_17 17
#define PWM_PIN_27 27
#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO 17 as PWM output */
    if (gpioSetMode(PWM_PIN_17, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_17, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_17, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO 27 as PWM output */
    if (gpioSetMode(PWM_PIN_27, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_27);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_27, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_27);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_27, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_27);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Apply a 50% duty cycle to both pins */
    if (gpioPWM(PWM_PIN_17, PWM_RANGE / 2) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_27, PWM_RANGE / 2) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_27);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM applied to GPIO %d and GPIO %d (50%% duty cycle)\n",
           PWM_PIN_17, PWM_PIN_27);

    /* Wait for signal or timeout */
    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown: turn off PWM and release pigpio */
    gpioPWM(PWM_PIN_17, 0);
    gpioPWM(PWM_PIN_27, 0);
    gpioTerminate();

    printf("PWM terminated cleanly\n");
    return EXIT_SUCCESS;
}

