#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_4  4
#define PWM_PIN_17 17
#define PWM_PIN_18 18
#define PWM_PIN_27 27

#define NUM_PINS 4
#define CYCLES 5
#define CYCLE_DELAY_US 60000000  /* 60 seconds in microseconds */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void cleanup(void) {
    /* Set pins to a safe state and release pigpio */
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_17, 0);
    gpioPWM(PWM_PIN_18, 0);
    gpioPWM(PWM_PIN_27, 0);
    gpioTerminate();
}

int main(void) {
    int pins[NUM_PINS] = {PWM_PIN_4, PWM_PIN_17, PWM_PIN_18, PWM_PIN_27};
    int duty_cycle = 128;  /* 50% of 255 */

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins as PWM outputs */
    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMrange(pins[i], 255) != 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Main loop: 5 cycles of 60-second PWM pulses */
    for (int cycle = 0; cycle < CYCLES && g_running; cycle++) {
        printf("Cycle %d/%d: Applying PWM duty cycle %d/255\n", cycle + 1, CYCLES, duty_cycle);
        fflush(stdout);

        for (int i = 0; i < NUM_PINS; i++) {
            if (gpioPWM(pins[i], duty_cycle) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                cleanup();
                return EXIT_FAILURE;
            }
        }

        /* Sleep for 60 seconds, checking for shutdown every second */
        for (int s = 0; s < 60 && g_running; s++) {
            gpioDelay(1000000);  /* 1 second */
        }
    }

    /* Graceful shutdown: turn off PWM and release pigpio */
    cleanup();
    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

