#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN_4  4
#define DHT22_PIN_17 17
#define MAX_CYCLES   3
#define READ_INTERVAL 60
#define MAX_RETRIES  3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_ms) {
    int elapsed = 0;
    while (gpiod_line_get_value(line) != level) {
        if (!g_running) return -1;
        usleep(1000);
        elapsed++;
        if (elapsed >= timeout_ms) return -1;
    }
    return 0;
}

static int read_dht22(struct gpiod_line *line, int pin, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (!g_running) return -1;

        if (gpiod_line_request_output(line, "dht22", 1) < 0) {
            fprintf(stderr, "Failed to request output on pin %d\n", pin);
            return -1;
        }
        gpiod_line_set_value(line, 1);
        usleep(500000);
        gpiod_line_set_value(line, 0);
        usleep(20000);

        if (gpiod_line_request_input(line, "dht22") < 0) {
            fprintf(stderr, "Failed to request input on pin %d\n", pin);
            return -1;
        }

        if (wait_for_level(line, 0, 1000) < 0) continue;
        if (wait_for_level(line, 1, 1000) < 0) continue;

        for (i = 0; i < 40; i++) {
            if (wait_for_level(line, 0, 1000) < 0) break;
            int t0 = 0;
            while (gpiod_line_get_value(line) == 1) {
                if (!g_running) return -1;
                usleep(1);
                t0++;
                if (t0 > 100) break;
            }
            if (t0 > 50) data[i / 8] |= (1 << (7 - (i % 8)));
        }

        if (i < 40) continue;

        uint8_t checksum = data[0] + data[1] + data[2] + data[3];
        if (checksum != data[4]) continue;

        uint16_t raw_h = (data[0] << 8) | data[1];
        uint16_t raw_t = (data[2] << 8) | data[3];

        *hum = raw_h / 10.0f;
        if (raw_t & 0x8000) {
            *temp = -(raw_t & 0x7FFF) / 10.0f;
        } else {
            *temp = raw_t / 10.0f;
        }

        if (*temp < -40.0f || *temp > 80.0f || *hum < 0.0f || *hum > 100.0f) {
            fprintf(stderr, "Invalid reading: T=%.1f H=%.1f\n", *temp, *hum);
            continue;
        }

        return 0;
    }

    fprintf(stderr, "Failed to read DHT22 on pin %d after %d retries\n", pin, MAX_RETRIES);
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN_4);
    if (!line) {
        perror("gpiod_chip_get_line(4)");
        goto cleanup;
    }

    for (int cycle = 0; cycle < MAX_CYCLES && g_running; cycle++) {
        float temp, hum;
        if (read_dht22(line, DHT22_PIN_4, &temp, &hum) == 0) {
            printf("Cycle %d: Pin 4 - Temp: %.1f C, Hum: %.1f %%\n", cycle + 1, temp, hum);
        } else {
            fprintf(stderr, "Cycle %d: Pin 4 read failed\n", cycle + 1);
        }

        if (cycle < MAX_CYCLES - 1 && g_running) {
            sleep(READ_INTERVAL);
        }
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN_17);
    if (!line) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    for (int cycle = 0; cycle < MAX_CYCLES && g_running; cycle++) {
        float temp, hum;
        if (read_dht22(line, DHT22_PIN_17, &temp, &hum) == 0) {
            printf("Cycle %d: Pin 17 - Temp: %.1f C, Hum: %.1f %%\n", cycle + 1, temp, hum);
        } else {
            fprintf(stderr, "Cycle %d: Pin 17 read failed\n", cycle + 1);
        }

        if (cycle < MAX_CYCLES - 1 && g_running) {
            sleep(READ_INTERVAL);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

