#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_17 17
#define PWM_PIN_18 18
#define PWM_PIN_27 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency to 1000 Hz for all three pins */
    if (gpioSetPWMfrequency(PWM_PIN_17, 1000) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_18, 1000) < 0 ||
        gpioSetPWMfrequency(PWM_PIN_27, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range to 255 for all three pins */
    if (gpioSetPWMrange(PWM_PIN_17, 255) < 0 ||
        gpioSetPWMrange(PWM_PIN_18, 255) < 0 ||
        gpioSetPWMrange(PWM_PIN_27, 255) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Main loop: apply a 50% duty cycle and report */
    while (running) {
        if (gpioPWM(PWM_PIN_17, 128) < 0 ||
            gpioPWM(PWM_PIN_18, 128) < 0 ||
            gpioPWM(PWM_PIN_27, 128) < 0) {
            fprintf(stderr, "Failed to set PWM value\n");
            break;
        }
        printf("GPIO %d: PWM 50%%\n", PWM_PIN_17);
        printf("GPIO %d: PWM 50%%\n", PWM_PIN_18);
        printf("GPIO %d: PWM 50%%\n", PWM_PIN_27);
        fflush(stdout);

        gpioDelay(1000000); /* 1 second */
    }

    /* Clean shutdown: turn off PWM and release pigpio */
    gpioPWM(PWM_PIN_17, 0);
    gpioPWM(PWM_PIN_18, 0);
    gpioPWM(PWM_PIN_27, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

