#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 4000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int spi_init(int *fd) {
    int ret;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED_HZ;

    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    ret = ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = 0;

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_max31855(int fd, float *temperature) {
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0) {
        return -1;
    }

    uint32_t raw = ((uint32_t)rx[0] << 24) | ((uint32_t)rx[1] << 16) |
                   ((uint32_t)rx[2] << 8) | (uint32_t)rx[3];

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X)\n", raw);
        return -1;
    }

    if (raw & 0x00000004) {
        fprintf(stderr, "Warning: MAX31855 not ready (raw=0x%08X)\n", raw);
    }

    int16_t temp_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (temp_raw & 0x2000) {
        temp_raw |= 0xC000;
    }

    *temperature = temp_raw * 0.25f;
    return 0;
}

int main(void) {
    int fd = -1;
    float temperature;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init(&fd) < 0) {
        return 1;
    }

    if (read_max31855(fd, &temperature) < 0) {
        close(fd);
        return 1;
    }

    printf("Temperature: %.2f C\n", temperature);
    close(fd);
    return 0;
}

