#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define ECHO_PIN2 18
#define ECHO_PIN3 27

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define MAX_DISTANCE_CM 400.0
#define SOUND_SPEED_CM_PER_US 0.0343

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static void trigger_pulse(struct gpiod_line *line) {
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("set trigger high");
        exit(EXIT_FAILURE);
    }
    usleep(TRIGGER_PULSE_US);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("set trigger low");
        exit(EXIT_FAILURE);
    }
}

static float measure_distance(struct gpiod_line *echo) {
    long long start = 0, end = 0;
    int val;

    trigger_pulse(echo);

    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("read echo");
            return -1.0f;
        }
        if (val == 1) {
            start = now_us();
            break;
        }
        if (now_us() - start > ECHO_TIMEOUT_US) {
            return -1.0f;
        }
    }
    if (!running) return -1.0f;

    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("read echo");
            return -1.0f;
        }
        if (val == 0) {
            end = now_us();
            break;
        }
        if (now_us() - end > ECHO_TIMEOUT_US) {
            return -1.0f;
        }
    }
    if (!running) return -1.0f;

    long long elapsed = end - start;
    float distance = (float)elapsed * SOUND_SPEED_CM_PER_US / 2.0f;
    return distance;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL, *echo = NULL, *echo2 = NULL, *echo3 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("open gpiochip0");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2 = gpiod_chip_get_line(chip, ECHO_PIN2);
    echo3 = gpiod_chip_get_line(chip, ECHO_PIN3);

    if (!trigger || !echo || !echo2 || !echo3) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hcsr04", 0) < 0) {
        perror("request trigger output");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hcsr04") < 0 ||
        gpiod_line_request_input(echo2, "hcsr04") < 0 ||
        gpiod_line_request_input(echo3, "hcsr04") < 0) {
        perror("request echo input");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        float d1 = measure_distance(echo);
        float d2 = measure_distance(echo2);
        float d3 = measure_distance(echo3);

        if (d1 < 0.0f || d2 < 0.0f || d3 < 0.0f) {
            printf("Sensor timeout or error.\n");
        } else {
            printf("Distances: %.2f cm, %.2f cm, %.2f cm\n", d1, d2, d3);
        }
        usleep(500000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (echo2) gpiod_line_release(echo2);
    if (echo3) gpiod_line_release(echo3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

