#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x03
#define I2C_BUS "/dev/i2c-1"

#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CALIB_26 0xE1

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int bmp280_read_calibration(int fd, bmp280_calib_t *cal) {
    uint8_t buf[26];
    if (i2c_read_reg(fd, BMP280_REG_CALIB_00, buf, 26) < 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[1] << 8 | buf[0]);
    cal->dig_T2 = (int16_t)(buf[3] << 8 | buf[2]);
    cal->dig_T3 = (int16_t)(buf[5] << 8 | buf[4]);
    cal->dig_P1 = (uint16_t)(buf[7] << 8 | buf[6]);
    cal->dig_P2 = (int16_t)(buf[9] << 8 | buf[8]);
    cal->dig_P3 = (int16_t)(buf[11] << 8 | buf[10]);
    cal->dig_P4 = (int16_t)(buf[13] << 8 | buf[12]);
    cal->dig_P5 = (int16_t)(buf[15] << 8 | buf[14]);
    cal->dig_P6 = (int16_t)(buf[17] << 8 | buf[16]);
    cal->dig_P7 = (int16_t)(buf[19] << 8 | buf[18]);
    cal->dig_P8 = (int16_t)(buf[21] << 8 | buf[20]);
    cal->dig_P9 = (int16_t)(buf[23] << 8 | buf[22]);

    uint8_t ext[7];
    if (i2c_read_reg(fd, BMP280_REG_CALIB_26, ext, 7) < 0) return -1;
    (void)ext;
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) return -1;
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: BMP280 not found (ID=0x%02X, expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) return -1;
    usleep(2000);

    uint8_t status;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg(fd, BMP280_REG_STATUS, &status, 1) < 0) return -1;
        if ((status & 0x01) == 0) break;
        usleep(2000);
    }
    if (status & 0x01) {
        fprintf(stderr, "Error: BMP280 reset timeout\n");
        return -1;
    }

    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bmp280_read(int fd, const bmp280_calib_t *cal, float *temp, float *press) {
    uint8_t data[6];
    if (i2c_read_reg(fd, BMP280_REG_PRESS_MSB, data, 6) < 0) return -1;

    int32_t raw_p = (int32_t)((data[0] << 12) | (data[1] << 4) | (data[2] >> 4));
    int32_t raw_t = (int32_t)((data[3] << 12) | (data[4] << 4) | (data[5] >> 4));

    double v1 = ((double)raw_t / 16384.0 - (double)cal->dig_T1 / 1024.0) * cal->dig_T2;
    double v2 = (((double)raw_t / 131072.0 - (double)cal->dig_T1 / 8192.0) *
                 ((double)raw_t / 131072.0 - (double)cal->dig_T1 / 8192.0)) * cal->dig_T3;
    double t_fine = v1 + v2;
    *temp = (float)(t_fine / 5120.0);

    double p1 = t_fine / 2.0 - 64000.0;
    double p2 = p1 * p1 * cal->dig_P6 / 32768.0;
    p2 = p2 + p1 * cal->dig_P5 * 2.0;
    p2 = p2 / 4.0 + cal->dig_P4 * 65536.0;
    p1 = (cal->dig_P3 * p1 * p1 / 524288.0 + cal->dig_P2 * p1) / 524288.0;
    p1 = (1.0 + p1 / 32768.0) * cal->dig_P1;
    if (p1 == 0.0) return -1;

    double p = 1048576.0 - (double)raw_p;
    p = (p - p2 / 4096.0) * 6250.0 / p1;
    p1 = cal->dig_P9 * p * p / 2147483648.0;
    p2 = p * cal->dig_P8 / 32768.0;
    p = p + (p1 + p2 + cal->dig_P7) / 16.0;
    *press = (float)(p / 100.0);

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed\n");
        close(fd);
        return 1;
    }

    bmp280_calib_t cal;
    if (bmp280_read_calibration(fd, &cal) < 0) {
        fprintf(stderr, "Error reading calibration data\n");
        close(fd);
        return 1;
    }

    int count = 0;
    while (count < 3 && !g_stop) {
        float temp, press;
        if (bmp280_read(fd, &cal, &temp, &press) < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            close(fd);
            return 1;
        }
        printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temp, press);
        fflush(stdout);
        count++;
        usleep(100000);
    }

    close(fd);
    return g_stop ? 130 : 0;
}

