#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define VEML7700_ADDR 0x10
#define VEML7700_REG_ALS 0x00
#define VEML7700_REG_CONFIG 0x01
#define VEML7700_REG_PS 0x02
#define VEML7700_REG_INT_CFG 0x03
#define VEML7700_REG_INT_STATUS 0x04
#define VEML7700_REG_ALS_IR 0x05
#define VEML7700_REG_PS_IR 0x06
#define VEML7700_REG_ALS_VIS 0x07
#define VEML7700_REG_PS_VIS 0x08

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint16_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val & 0xFF);
    buf[2] = (uint8_t)((val >> 8) & 0xFF);
    if (write(fd, buf, 3) != 3) {
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", VEML7700_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint16_t config = 0x0000;
    if (i2c_write_reg(fd, VEML7700_REG_CONFIG, config) < 0) {
        fprintf(stderr, "Error writing config register: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        uint16_t als = 0;
        if (i2c_read_reg(fd, VEML7700_REG_ALS, &als) < 0) {
            fprintf(stderr, "Error reading ALS: %s\n", strerror(errno));
        } else {
            printf("ALS: %u\n", als);
        }
        usleep(500000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_TIMEOUT_MS 1000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int setup_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = READ_TIMEOUT_MS / 100;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_line(int fd, char *buf, size_t buf_size) {
    size_t i = 0;
    char ch;
    while (i < buf_size - 1) {
        ssize_t n = read(fd, &ch, 1);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                return 0;
            }
            fprintf(stderr, "Read error: %s\n", strerror(errno));
            return -1;
        } else if (n == 0) {
            return 0;
        }
        if (ch == '\n') {
            buf[i] = '\0';
            return (int)i;
        }
        buf[i++] = ch;
    }
    buf[i] = '\0';
    return (int)i;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    int fd = setup_serial(SERIAL_PORT);
    if (fd < 0) {
        return 1;
    }

    char line[256];
    int consecutive_empty = 0;

    while (!g_stop) {
        int n = read_line(fd, line, sizeof(line));
        if (n < 0) {
            break;
        }
        if (n == 0) {
            consecutive_empty++;
            if (consecutive_empty > 50) {
                fprintf(stderr, "No data from device after 5 s; exiting.\n");
                break;
            }
            continue;
        }
        consecutive_empty = 0;
        printf("Received: %s\n", line);
        fflush(stdout);
        usleep(POLL_INTERVAL_US);
    }

    tcflush(fd, TCIOFLUSH);
    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US  50000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static long long now_us(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (long long)ts.tv_sec * 1000000LL + ts.tv_nsec / 1000LL;
}

static float get_distance(struct gpiod_line *trig, struct gpiod_line *echo) {
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(2);

    if (gpiod_line_set_value(trig, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high: %s\n", strerror(errno));
        return -1.0f;
    }
    usleep(10);

    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low: %s\n", strerror(errno));
        return -1.0f;
    }

    long long start_wait = now_us();
    while (gpiod_line_get_value(echo) == 0) {
        if (now_us() - start_wait > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo start\n");
            return -1.0f;
        }
    }
    long long start_tick = now_us();

    while (gpiod_line_get_value(echo) == 1) {
        if (now_us() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: timeout waiting for echo end\n");
            return -1.0f;
        }
    }
    long long end_tick = now_us();

    long long diff = end_tick - start_tick;
    float distance = (float)diff / 58.0f;

    if (distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Error: distance out of range (%.2f cm)\n", distance);
        return -1.0f;
    }

    return distance;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        float distance = get_distance(trig, echo);
        if (distance >= 0.0f) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: failed to get distance\n");
        }
        sleep(1);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 8

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request the line as output, initial value 0 */
    if (gpiod_line_request_output(line, "gpio8-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    /* Main loop: toggle every 1 ms */
    while (running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            perror("gpiod_line_get_value");
            goto cleanup;
        }

        if (gpiod_line_set_value(line, val ? 0 : 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }

        printf("GPIO 8 set to %d\n", val ? 0 : 1);
        fflush(stdout);

        usleep(1000); /* 1 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int sig) {
    (void)sig;
    g_stop = 1;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error setting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading %d bytes from reg 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", ADXL345_ADDRESS, strerror(errno));
        goto cleanup;
    }

    if (i2c_write_reg(fd, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) goto cleanup;
    if (i2c_write_reg(fd, ADXL345_REG_BW_RATE, 0x0A) < 0) goto cleanup;
    if (i2c_write_reg(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) goto cleanup;

    uint8_t data[6];
    if (i2c_read_regs(fd, ADXL345_REG_DATAX0, data, 6) < 0) goto cleanup;

    int16_t x = (int16_t)((data[1] << 8) | data[0]);
    int16_t y = (int16_t)((data[3] << 8) | data[2]);
    int16_t z = (int16_t)((data[5] << 8) | data[4]);

    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_PINS 8
static const unsigned int pins[NUM_PINS] = {4, 17, 18, 22, 23, 24, 25, 27};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio_toggle", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %u\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read line %u\n", pins[i]);
                goto cleanup;
            }
            val = val ? 0 : 1;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to write line %u\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %u: %d\n", pins[i], val);
        }
        fflush(stdout);
        usleep(50000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27
#define CONSUMER "gpio_control"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3];
    int pins[3] = {GPIO_4, GPIO_17, GPIO_27};
    int i;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request output for line %d\n", pins[i]);
            goto cleanup;
        }
