#include <pigpio.h>
#include <stdio.h>
#include <signal.h>
#include <stdlib.h>

#define PWM_PIN_4  4
#define PWM_PIN_22 22
#define PWM_RANGE  255
#define PWM_FREQ   1000
#define STEP_US    10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure both pins as hardware-PWM outputs */
    if (gpioSetMode(PWM_PIN_4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_22, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_22);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM range and frequency */
    if (gpioSetPWMrange(PWM_PIN_4, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_22, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN_22);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_4);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN_22, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN_22);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int val = 0;
    int increment = 1;

    while (running) {
        if (gpioPWM(PWM_PIN_4, val) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_4);
            break;
        }
        if (gpioPWM(PWM_PIN_22, val) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_22);
            break;
        }
        printf("GPIO %d: PWM %d/%d\n", PWM_PIN_4, val, PWM_RANGE);
        printf("GPIO %d: PWM %d/%d\n", PWM_PIN_22, val, PWM_RANGE);
        fflush(stdout);

        val += increment;
        if (val >= PWM_RANGE) {
            val = PWM_RANGE - 1;
            increment = -1;
        } else if (val <= 0) {
            val = 1;
            increment = 1;
        }

        gpioDelay(STEP_US);
    }

    /* Clean shutdown: turn off PWM and release pigpio */
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_22, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
