#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define OUTPUT_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *out = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    out = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!trig || !echo || !out) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(out, "hcsr04-out", 0) < 0) {
        perror("gpiod_line_request_output(out)");
        goto cleanup;
    }

    /* Trigger: 10 us high pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trig,1)");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trig,0)");
        goto cleanup;
    }

    /* Output: 5 V (active high) for 100 ms */
    if (gpiod_line_set_value(out, 1) < 0) {
        perror("gpiod_line_set_value(out,1)");
        goto cleanup;
    }
    usleep(100000);
    if (gpiod_line_set_value(out, 0) < 0) {
        perror("gpiod_line_set_value(out,0)");
        goto cleanup;
    }

    printf("Triggered 10 us pulse on GPIO %d\n", TRIGGER_PIN);
    printf("Output 5 V for 100 ms on GPIO %d\n", OUTPUT_PIN);
    printf("Echo input on GPIO %d\n", ECHO_PIN);
    printf("Program finished.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (out) gpiod_line_release(out);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

