    /* Wait for signal or timeout */
    while (running) {
        gpioDelay(100000); /* 100 ms */
    }

    /* Clean shutdown: turn off PWM and release pigpio */
    gpioPWM(PWM_PIN_18, 0);
    gpioPWM(PWM_PIN_21, 0);
    gpioPWM(PWM_PIN_22, 0);
    gpioTerminate();

    printf("\nPWM terminated cleanly.\n");
    return EXIT_SUCCESS;
}

