#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_I2C_ADDR 0x29
#define TCS34725_CMD_BIT  0x80
#define TCS34725_ENABLE   0x00
#define TCS34725_ATIME    0x01
#define TCS34725_CONTROL  0x0F
#define TCS34725_CDATA    0x14
#define TCS34725_RDATA    0x16
#define TCS34725_GDATA    0x18
#define TCS34725_BDATA    0x1A

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { (uint8_t)(reg | TCS34725_CMD_BIT), val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *val) {
    uint8_t cmd = (uint8_t)(reg | TCS34725_CMD_BIT);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    if (i2c_write(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    if (i2c_write(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    if (i2c_write(fd, TCS34725_CONTROL, 0x01) < 0) return -1;
    return 0;
}

static int tcs34725_read(int fd, uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t r_lo, r_hi, g_lo, g_hi, b_lo, b_hi;
    if (i2c_read(fd, TCS34725_CDATA, &r_lo) < 0) return -1;
    if (i2c_read(fd, TCS34725_CDATA + 1, &r_hi) < 0) return -1;
    if (i2c_read(fd, TCS34725_RDATA, &g_lo) < 0) return -1;
    if (i2c_read(fd, TCS34725_RDATA + 1, &g_hi) < 0) return -1;
    if (i2c_read(fd, TCS34725_GDATA, &b_lo) < 0) return -1;
    if (i2c_read(fd, TCS34725_GDATA + 1, &b_hi) < 0) return -1;
    *r = (uint16_t)((r_hi << 8) | r_lo);
    *g = (uint16_t)((g_hi << 8) | g_lo);
    *b = (uint16_t)((b_hi << 8) | b_lo);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed (device may be absent).\n");
        close(fd);
        return 1;
    }

    while (g_running) {
        uint16_t r, g, b;
        if (tcs34725_read(fd, &r, &g, &b) == 0) {
            printf("R: %u, G: %u, B: %u\n", r, g, b);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; continuing.\n");
        }
        usleep(500000);
    }

    i2c_write(fd, TCS34725_ENABLE, 0x00);
    close(fd);
    return 0;
}

