#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_TIMEOUT_MS 1000
#define LOOP_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int setup_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = (READ_TIMEOUT_MS / 100);

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static int read_serial_line(int fd, char *buf, size_t buf_size) {
    size_t i = 0;
    char ch;
    while (i < buf_size - 1) {
        ssize_t n = read(fd, &ch, 1);
        if (n == 1) {
            if (ch == '\n') {
                buf[i] = '\0';
                return (int)i;
            }
            buf[i++] = ch;
        } else if (n == 0) {
            return -1;
        } else {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                return -1;
            }
            perror("read");
            return -1;
        }
    }
    buf[i] = '\0';
    return (int)i;
}

static void cleanup_serial(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main(void) {
    if (setup_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    int fd = init_serial(SERIAL_PORT);
    if (fd == -1) {
        fprintf(stderr, "Failed to initialize serial port %s\n", SERIAL_PORT);
        return EXIT_FAILURE;
    }

    char buffer[256];

    while (g_running) {
        int bytes_read = read_serial_line(fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
            fflush(stdout);
        } else if (bytes_read == 0) {
            usleep(LOOP_DELAY_MS * 1000);
        } else {
            fprintf(stderr, "Error reading from serial port\n");
            cleanup_serial(fd);
            return EXIT_FAILURE;
        }
    }

    cleanup_serial(fd);
    return EXIT_SUCCESS;
}

