    if (gpiod_line_request_output(line5, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (GPIO 5)");
        goto cleanup;
    }

    /* Toggle states every second until interrupted */
    while (running) {
        if (gpiod_line_set_value(line3, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 3, high)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line5, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 5, low)");
            goto cleanup;
        }
        printf("GPIO 3: HIGH, GPIO 5: LOW\n");
        fflush(stdout);
        sleep(1);

        if (!running) break;

        if (gpiod_line_set_value(line3, 0) < 0) {
            perror("gpiod_line_set_value (GPIO 3, low)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line5, 1) < 0) {
            perror("gpiod_line_set_value (GPIO 5, high)");
            goto cleanup;
        }
        printf("GPIO 3: LOW, GPIO 5: HIGH\n");
        fflush(stdout);
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are released even on error */
    if (line3) gpiod_line_release(line3);
    if (line5) gpiod_line_release(line5);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN 23
#define OUTPUT_PIN 24

#define CONSUMER "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *out = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    out = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!trig || !echo || !out) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (trigger)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input (echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(out, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output (output)");
        goto cleanup;
    }

    /* Send 10us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value (trig high)");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value (trig low)");
        goto cleanup;
    }

    /* Wait for echo rising edge (max ~23ms for 4m range) */
    int val;
    int waited = 0;
    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value (echo)");
            goto cleanup;
        }
        if (val == 1) break;
        usleep(10);
        waited += 10;
        if (waited > 23000) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            goto cleanup;
        }
    }

    if (!running) goto cleanup;

    /* Wait for echo falling edge */
    waited = 0;
    while (running) {
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value (echo)");
            goto cleanup;
        }
        if (val == 0) break;
        usleep(10);
        waited += 10;
        if (waited > 23000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            goto cleanup;
        }
    }

    if (!running) goto cleanup;

    /* Calculate distance (speed of sound ~343 m/s) */
    long pulse_us = waited;
    float distance = (pulse_us * 0.0343f) / 2.0f;
    printf("Distance: %.2f cm\n", distance);

    /* Set output high if distance < 10cm, else low */
    if (distance < 10.0f) {
        if (gpiod_line_set_value(out, 1) < 0) {
            perror("gpiod_line_set_value (out high)");
            goto cleanup;
        }
        printf("Output HIGH\n");
    } else {
        if (gpiod_line_set_value(out, 0) < 0) {
            perror("gpiod_line_set_value (out low)");
            goto cleanup;
        }
        printf("Output LOW\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (out) gpiod_line_release(out);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

