#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CHIP_NAME "gpiochip0"
#define NUM_PINS 3
static const unsigned int pins[NUM_PINS] = {18, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_request_output(lines[i], "gpio-toggle", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %u\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < NUM_PINS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read line %u\n", pins[i]);
                goto cleanup;
            }
            val = !val;
            if (gpiod_line_set_value(lines[i], val) < 0) {
                fprintf(stderr, "Failed to write line %u\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %u: %d\n", pins[i], val);
        }
        fflush(stdout);
        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        uint8_t buf[6];
        if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            break;
        }

        int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

        printf("X: %d, Y: %d, Z: %d\n", accel_x, accel_y, accel_z);
        fflush(stdout);

        sleep(1);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define PERIOD_MS 600

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "gpio17-toggle", 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    int value = 0;
    while (running) {
        if (gpiod_line_set_value(line, value) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, value);
        fflush(stdout);
        value = !value;
        usleep(PERIOD_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}
